{'type': '五言绝句', 'content': [{'chapter': '春眠', 'author': '（唐）孟浩然', 'paragraphs': ['春眠不觉晓，处处闻啼鸟。', '夜来风雨声，花落知多少。']}, {'chapter': '访袁拾遗不遇', 'author': '（唐）孟浩然', 'paragraphs': ['洛阳访才子，江岭作流人。', '闻说梅花早，何如此地春。']}, {'chapter': '送郭司仓', 'author': '（唐）王昌龄', 'paragraphs': ['映门淮水绿，留骑主人心。', '明月随良掾，春潮夜夜深。']}, {'chapter': '洛阳道', 'author': '（唐）储光羲', 'paragraphs': ['大道直如发，春来佳气多。', '五陵贵公子，双双鸣玉珂。']}, {'chapter': '独坐敬亭山', 'author': '（唐）李白', 'paragraphs': ['众鸟高飞尽，孤云独去闲。', '相看两不厌，只有敬亭山。']}, {'chapter': '登鹳雀楼', 'author': '（唐）王之涣', 'paragraphs': ['白日依山尽，黄河入海流。', '欲穷千里目，更上一层楼。']}, {'chapter': '观永乐公主入番', 'author': '（唐）孙逖', 'paragraphs': ['边地莺花少，年来未觉新。', '美人天上落，龙塞始应春。']}, {'chapter': '伊州歌', 'author': '（唐）金昌绪', 'paragraphs': ['打起黄莺儿，莫教枝上啼。', '啼时惊妾梦，不得到辽西。']}, {'chapter': '左掖梨花', 'author': '（唐）丘为', 'paragraphs': ['冷艳全欺雪，余香乍入衣。', '春风且莫定，吹向玉阶飞。']}, {'chapter': '思君恩', 'author': '（唐）令狐楚', 'paragraphs': ['小苑莺歌歇，长门蝶舞多。', '眼看春又去，翠辇不曾过。']}, {'chapter': '题袁氏别业', 'author': '（唐）贺知章', 'paragraphs': ['主人不相识，偶坐为林泉。', '莫谩愁沽酒，囊中自有钱。']}, {'chapter': '夜送赵纵', 'author': '（唐）杨炯', 'paragraphs': ['赵氏连城璧，由来天下传。', '送君还旧府，明月满前川。']}, {'chapter': '竹里馆', 'author': '（唐）王维', 'paragraphs': ['独坐幽篁里，弹琴复长啸。', '深林人不知，明月来相照。']}, {'chapter': '送朱大入秦', 'author': '（唐）王维', 'paragraphs': ['避人五陵去，宝剑值千金。', '分手脱相赠，平生一片心。']}, {'chapter': '长干行', 'author': '（唐）崔颢', 'paragraphs': ['君家在何处？妾住在横塘。', '停船暂借问，或恐是同乡。']}, {'chapter': '咏史', 'author': '（唐）高适', 'paragraphs': ['尚有绨袍赠，应怜范叔寒。', '不知天下士，犹作布衣看。']}, {'chapter': '罢相作', 'author': '（唐）李适之', 'paragraphs': ['避贤初罢相，乐圣且衔杯。', '为问门前客，今朝几个来。']}, {'chapter': '逢侠者', 'author': '（唐）钱起', 'paragraphs': ['燕赵悲歌士，相逢剧孟家。', '寸心言不尽，前路日将斜。']}, {'chapter': '江行望匡庐', 'author': '（唐）钱起', 'paragraphs': ['咫尺愁风雨，匡庐不可登。', '只疑云雾窟，犹有六朝僧。']}, {'chapter': '答李浣', 'author': '（唐）韦应物', 'paragraphs': ['林中观易罢，溪上对鸥闲。', '楚俗饶词客，何人最往还。']}, {'chapter': '秋风引', 'author': '（唐）刘禹锡', 'paragraphs': ['何处秋风至，萧萧送雁群。', '朝来入庭树，孤客最先闻。']}, {'chapter': '秋夜寄丘员外', 'author': '（唐）韦应物', 'paragraphs': ['怀君属秋夜，散步咏凉天。', '山空松子落，幽人应未眠。']}, {'chapter': '秋日', 'author': '（唐）耿𣲗', 'paragraphs': ['返照入闾巷，忧来谁共语。', '古道少人行，秋风动禾黍。']}, {'chapter': '秋日湖上', 'author': '（唐）薛莹', 'paragraphs': ['落日五湖游，烟波处处愁。', '浮沉千古事，谁与问东流。']}, {'chapter': '宫中题', 'author': '（唐）李昂', 'paragraphs': ['辇路生秋草，上林花满枝。', '凭高何限意，无复侍臣知。']}, {'chapter': '汾上惊秋', 'author': '（唐）苏颋', 'paragraphs': ['北风吹白云，万里渡河汾。', '心绪逢摇落，秋声不可闻。']}, {'chapter': '寻隐者不遇', 'author': '（唐）贾岛', 'paragraphs': ['松下问童子，言师采药去。', '只在此山中，云深不知处。']}, {'chapter': '蜀道后期', 'author': '（唐）张说', 'paragraphs': ['客心争日月，来往预期程。', '秋风不相待，先至洛阳城。']}, {'chapter': '静夜思', 'author': '（唐）李白', 'paragraphs': ['床前明月光，疑是地上霜。', '举头望明月，低头思故乡。']}, {'chapter': '秋浦歌', 'author': '（唐）李白', 'paragraphs': ['白发三千丈，缘愁似个长。', '不知明镜里，何处得秋霜。']}, {'chapter': '赠乔侍郎', 'author': '（唐）陈子昂', 'paragraphs': ['汉廷荣巧宦，云阁薄边功。', '可怜骢马使，白首为谁雄。']}, {'chapter': '答五陵太守', 'author': '（唐）王昌龄', 'paragraphs': ['仗剑行千里，微躯敢一言。', '曾为大梁客，不负信陵恩。']}, {'chapter': '行军九日思长安故园', 'author': '（唐）岑参', 'paragraphs': ['强欲登高去，无人送酒来。', '遥怜故园菊，应傍战场开。']}, {'chapter': '婕妤怨', 'author': '（唐）皇甫冉', 'paragraphs': ['花枝出建章，凤管发昭阳。', '借问承恩者，双蛾几许长？']}, {'chapter': '题竹林寺', 'author': '（唐）朱放', 'paragraphs': ['岁月人间促，烟霞此地多。', '殷勤竹林寺，更得几回过？']}, {'chapter': '过三闾庙', 'author': '（唐）戴叔伦', 'paragraphs': ['沅湘流不尽，屈子怨何深！', '日暮秋风起，萧萧枫树林。']}, {'chapter': '易水送别', 'author': '（唐）骆宾王', 'paragraphs': ['此地别燕丹，壮士发冲冠。', '昔时人已没，今日水犹寒。']}, {'chapter': '别卢秦卿', 'author': '（唐）司空曙', 'paragraphs': ['知有前期在，难分此夜中。', '无将故人酒，不及石尤风。']}, {'chapter': '答人', 'author': '（唐）太上隐者', 'paragraphs': ['偶来松树下，高枕石头眠。', '山中无历日，寒尽不知年。']}]}
{'type': '五言律诗', 'content': [{'chapter': '幸蜀回至剑门', 'author': '（唐）李隆基', 'paragraphs': ['剑阁横云峻，銮舆出狩回。', '翠屏千仞合，丹嶂五丁开。', '灌木萦旗转，仙云拂马来。', '乘时方在德，嗟尔勒铭才。']}, {'chapter': '和晋陵陆承相', 'author': '（唐）杜审言', 'paragraphs': ['独有宦游人，偏惊物候新。', '云霞出海曙，梅柳渡江春。', '淑气催黄鸟，晴光转绿苹。', '忽闻歌古调，归思欲沾巾。']}, {'chapter': '蓬莱三殿侍宴奉敕咏终南山', 'author': '（唐）杜审言', 'paragraphs': ['北斗挂城边，南山倚殿前。', '云标金阙迥，树杪玉堂悬。', '半岭通佳气，中峰绕瑞烟。', '小臣持献寿，长此戴尧天。']}, {'chapter': '春夜别友人', 'author': '（唐）陈子昂', 'paragraphs': ['银烛吐青烟，金尊对绮筵。', '离堂思琴瑟，别路绕山川。', '明月隐高树，长河没晓天。', '悠悠洛阳道，此会在何年。']}, {'chapter': '长宁公主东庄侍宴', 'author': '（唐）李峤', 'paragraphs': ['别业临青甸，鸣銮降紫霄。', '长筵鹓鹭集，仙管凤凰调。', '树接南山近，烟含北渚遥。', '承恩咸已醉，恋赏未还镳。']}, {'chapter': '恩赐丽正殿书院赐宴应制得林字', 'author': '（唐）张说', 'paragraphs': ['东壁图书府，西园翰墨林。', '诵诗闻国政，讲易见天心。', '位窃和羹重，恩叨醉酒深。', '载歌春兴曲，情竭为知音。']}, {'chapter': '送友人', 'author': '（唐）李白', 'paragraphs': ['青山横北郭，白水绕东城。', '此地一为别，孤篷万里征。', '浮云游子意，落日故人情。', '挥手自兹去，萧萧斑马鸣。']}, {'chapter': '送友人入蜀', 'author': '（唐）李白', 'paragraphs': ['见说蚕丛路，崎岖不易行。', '山从人面起，云傍马头生。', '芳树笼秦栈，春流绕蜀城。', '升沈应已定，不必问君平。']}, {'chapter': '次北固山下', 'author': '（唐）王湾', 'paragraphs': ['客路青山外，行舟绿水前。', '潮平两岸阔，风正一帆悬。', '海日生残夜，江春入旧年。', '乡书何处达，归雁洛阳边。']}, {'chapter': '苏氏别业', 'author': '（唐）祖咏', 'paragraphs': ['别业居幽处，到来生隐心。', '南山当户牖，澧水映园林。', '竹覆经冬雪，庭昏未夕阴。', '寥寥人境外，闲坐听春禽。']}, {'chapter': '春宿左省', 'author': '（唐）杜甫', 'paragraphs': ['花隐掖垣暮，啾啾栖鸟过。', '星临万户动，月傍九霄多。', '不寝听金钥，因风想玉珂。', '明朝有封事，数问夜如何？']}, {'chapter': '题玄武禅师屋壁', 'author': '（唐）杜甫', 'paragraphs': ['何年顾虎头，满壁画沧州。', '赤日石林气，青天江海流。', '锡飞常近鹤，杯渡不惊鸥。', '似得庐山路，真随惠远游。']}, {'chapter': '终南山', 'author': '（唐）王维', 'paragraphs': ['太乙近天都，连山到海隅。', '白云回望合，青霭入看无。', '分野中峰变，阴晴众壑殊。', '欲投人处宿，隔水问樵夫。']}, {'chapter': '登总持阁', 'author': '（唐）岑参', 'paragraphs': ['高阁逼诸天，登临近日边。', '晴开万井树，愁看五陵烟。', '槛外低秦岭，窗中小渭川。', '早知清净理，常愿奉金仙。']}, {'chapter': '寄左省杜拾遗', 'author': '（唐）岑参', 'paragraphs': ['联步趋丹陛，分曹限紫薇。', '晓随天仗入，暮惹御香归。', '白发悲花落，青云羡鸟飞。', '圣朝无阙事，自觉谏书稀。']}, {'chapter': '登兖州城楼', 'author': '（唐）杜甫', 'paragraphs': ['东郡趋庭日，南楼纵目初。', '浮云连海岱，平野入青徐。', '孤嶂秦碑在，荒城鲁殿余。', '从来多古意，临眺独踌躇。']}, {'chapter': '杜少府之任蜀州', 'author': '（唐）王勃', 'paragraphs': ['城阙辅三秦，风烟望五津。', '与君离别意，同是宦游人。', '海内存知己，天涯若比邻。', '无为在歧路，儿女共沾巾。']}, {'chapter': '送崔融', 'author': '（唐）杜审言', 'paragraphs': ['君王行出将，书记远从征。', '祖帐连河阙，军麾动洛城。', '旌旗朝朔气，笳吹夜边声。', '坐觉烟尘扫，秋风古北平。']}, {'chapter': '扈从登封途中作', 'author': '（唐）宋之问', 'paragraphs': ['帐殿郁崔嵬，仙游实壮哉！', '晓云连幕卷，夜火杂星回。', '谷暗千旗出，山鸣万乘来。', '扈从良可赋，终乏掞天才。']}, {'chapter': '题义公禅房', 'author': '（唐）孟浩然', 'paragraphs': ['义公习禅寂，结宇依空林。', '户外一峰秀，阶前众壑深。', '夕阳连雨足，空翠落庭阴。', '看取莲花净，方知不染心。']}, {'chapter': '醉后赠张九旭', 'author': '（唐）高适', 'paragraphs': ['世上漫相识，此翁殊不然。', '兴来书自圣，醉后语尤颠。', '白发老闲事，青云在目前。', '床头一壶酒，能更几回眠。']}, {'chapter': '玉台观', 'author': '（唐）高适', 'paragraphs': ['浩劫因王造，平台访古游。', '彩云萧史驻，文字鲁恭留。', '宫阙通群帝，乾坤到十洲。', '人传有笙鹤，时过北山头。']}, {'chapter': '观李固请司马弟山水图', 'author': '（唐）杜甫', 'paragraphs': ['方丈浑连水，天台总映云。', '人间长见画，老去恨空闻。', '范蠡舟偏小，王乔鹤不群。', '此生随万物，何处出尘氛。']}, {'chapter': '旅夜书怀', 'author': '（唐）杜甫', 'paragraphs': ['细草微风岸，危樯独夜舟。', '星垂平野阔，月涌大江流。', '名岂文章著，官因老病休。', '飘飘何所似，天地一沙鸥。']}, {'chapter': '登岳阳楼', 'author': '（唐）杜甫', 'paragraphs': ['昔闻洞庭水，今上岳阳楼。', '吴楚东南坼，乾坤日夜浮。', '亲朋无一字，老病有孤舟。', '戎马关山北，凭轩涕泗流。']}, {'chapter': '江南旅情', 'author': '（唐）祖咏', 'paragraphs': ['楚山不可极，归路但萧条。', '海色晴看雨，江声夜听潮。', '剑留南斗近，书寄北风遥。', '为报空潭橘，无媒寄洛桥。']}, {'chapter': '宿龙兴寺', 'author': '（唐）綦毋潜', 'paragraphs': ['香刹夜忘归，松清古殿扉。', '灯明方丈室，珠系比丘衣。', '白日传心净，青莲喻法微。', '天花落不尽，处处鸟衔飞。']}, {'chapter': '破山寺后禅院', 'author': '（唐）常建', 'paragraphs': ['清晨入古寺，初日照高林。', '曲径通幽处，禅房花木深。', '山光悦鸟性，潭影空人心。', '万籁此俱寂，惟闻钟磬音。']}, {'chapter': '题松汀驿', 'author': '（唐）张佑', 'paragraphs': ['山色远含空，苍茫泽国东。', '海明先见日，江白迥闻风。', '鸟道高原去，人烟小径通。', '那知旧遗逸，不在五湖中。']}, {'chapter': '圣果寺', 'author': '（唐）释处默', 'paragraphs': ['路自中峰上，盘回出薜萝。', '到江吴地尽，隔岸越山多。', '古木丛青蔼，遥天浸白波。', '下方城郭近，钟磬杂笙歌。']}, {'chapter': '野望', 'author': '（唐）王绩', 'paragraphs': ['东皋薄暮望，徙倚欲何依。', '树树皆秋色，山山惟落晖。', '牧人驱犊返，猎马带禽归。', '相顾无相识，长歌怀采薇。']}, {'chapter': '送著作佐郎崔融等从梁王东征', 'author': '（唐）陈子昂', 'paragraphs': ['金天方肃杀，白露始专征。', '王师非乐战，之子慎佳兵。', '海气侵南部，边风扫北平。', '莫卖卢龙塞，归邀麟阁名。']}, {'chapter': '携妓纳凉晚际遇雨', 'author': '（唐）杜甫', 'paragraphs': [{'subchapter': '其一', 'paragraphs': ['落日放船好，轻风生浪迟。', '竹深留客处，荷净纳凉时。', '公子调冰水，佳人雪藕丝。', '片云头上黑，应是雨催诗。']}, {'subchapter': '其二', 'paragraphs': ['雨来沾席上，风急打船头。', '越女红裙湿，燕姬翠黛愁。', '缆侵堤柳系，幔卷浪花浮。', '归路翻萧飒，陂塘五月秋。']}]}, {'chapter': '宿云门寺阁', 'author': '（唐）孙逖', 'paragraphs': ['香阁东山下，烟花象外幽。', '悬灯千嶂夕，卷幔五湖秋。', '画壁余鸿雁，纱窗宿斗牛。', '更疑天路近，梦与白云游。']}, {'chapter': '秋登宣城谢眺北楼', 'author': '（唐）李白', 'paragraphs': ['江城如画里，山晚望晴空。', '两水夹明镜，双桥落彩虹。', '人烟寒橘柚，秋色老梧桐。', '谁念北楼上，临风怀谢公。']}, {'chapter': '临洞庭', 'author': '（唐）孟浩然', 'paragraphs': ['八月湖水平，涵虚混太清。', '气蒸云梦泽，波撼岳阳城。', '欲济无舟楫，端居耻圣明。', '坐观垂钓者，徒有羡鱼情。']}, {'chapter': '过香积寺', 'author': '（唐）王维', 'paragraphs': ['不知香积寺，数里入云峰。', '古木无人径，深山何处钟。', '泉声咽危石，日色冷青松。', '薄暮空潭曲，安禅制毒龙。']}, {'chapter': '送郑侍御谪闽中', 'author': '（唐）高适', 'paragraphs': ['谪去君无恨，闽中我旧过。', '大都秋雁少，只是夜猿多。', '东路云山合，南天瘴疠和。', '自当逢雨露，行矣慎风波。']}, {'chapter': '秦州杂诗', 'author': '（唐）杜甫', 'paragraphs': ['凤林戈未息，鱼海路常难。', '候火云峰峻，悬军幕井干。', '风连西极动，月过北庭寒。', '故老思飞将，何时议筑坛。']}, {'chapter': '禹庙', 'author': '（唐）杜甫', 'paragraphs': ['禹庙空山里，秋风落日斜。', '荒庭垂橘柚，古屋画龙蛇。', '云气生虚壁，江声走白沙。', '早知乘四载，疏凿控三巴。']}, {'chapter': '望秦川', 'author': '（唐）李颀', 'paragraphs': ['秦川朝望迥，日出正东峰。', '远近山河净，逶迤城阙重。', '秋声万户竹，寒色五陵松。', '有客归欤叹，凄其霜露浓。']}, {'chapter': '同王征君洞庭有怀', 'author': '（唐）张谓', 'paragraphs': ['八月洞庭秋，潇湘水北流。', '还家万里梦，为客五更愁。', '不用开书帙，偏宜上酒楼。', '故人京洛满，何日复同游。']}, {'chapter': '渡扬子江', 'author': '（唐）丁仙芝', 'paragraphs': ['桂楫中流望，空波两岸明。', '林开扬子驿，山出润州城。', '海尽边阴静，江寒朔吹生。', '更闻枫叶下，淅沥度秋声。']}, {'chapter': '幽州夜歌', 'author': '（唐）张说', 'paragraphs': ['凉风吹夜雨，萧瑟动寒林。', '正有高堂宴，能忘迟暮心。', '军中宜剑舞，塞上重笳音。', '不作边城将，谁知恩遇深。']}]}
{'type': '七言绝句', 'content': [{'chapter': '春日偶成', 'author': '（宋）程颢', 'paragraphs': ['云淡风轻近午天，傍花随柳过前川。', '时人不识余心乐，将谓偷闲学少年。']}, {'chapter': '春日', 'author': '（宋）朱熹', 'paragraphs': ['胜日寻芳泗水滨，无边光景一时新。', '等闲识得东风面，万紫千红总是春。']}, {'chapter': '春宵', 'author': '（宋）苏轼', 'paragraphs': ['春宵一刻值千金，花有清香月有阴。', '歌管楼台声细细，秋千院落夜沈沈。']}, {'chapter': '城东早春', 'author': '（唐）杨巨源', 'paragraphs': ['诗家清景在新春，绿柳才黄半未匀。', '若待上林花似锦，出门俱是看花人。']}, {'chapter': '春夜', 'author': '（宋）王安石', 'paragraphs': ['金炉香烬漏声残，剪剪轻风阵阵寒。', '春色恼人眠不得，月移花影上栏杆。']}, {'chapter': '初春小雨', 'author': '（宋）韩愈', 'paragraphs': ['天街小雨润如酥，草色遥看近却无。', '最是一年春好处，绝胜烟柳满皇都。']}, {'chapter': '元日', 'author': '（宋）王安石', 'paragraphs': ['爆竹声中一岁除，春风送暖入屠苏。', '千门万户曈曈日，总把新桃换旧符。']}, {'chapter': '上元侍宴', 'author': '（宋）苏轼', 'paragraphs': ['淡月疏星绕建章，仙风吹下御炉香。', '侍臣鹄立通明殿，一朵红云捧玉皇。']}, {'chapter': '立春偶成', 'author': '（宋）张栻', 'paragraphs': ['律回岁晚冰霜少，春到人间草木知。', '便觉眼前生意满，东风吹水绿参差。']}, {'chapter': '打球图', 'author': '（宋）晁无咎', 'paragraphs': ['阊阖千门万户开，三郎沈醉打球回。', '九龄已老韩休死，无复明朝谏疏来。']}, {'chapter': '宫词', 'author': '（宋）林洪', 'paragraphs': [{'subchapter': '其一', 'paragraphs': ['金殿当头紫阁重，仙人掌上玉芙蓉。', '太平天子朝元日，五色云车驾六龙。']}, {'subchapter': '其二', 'paragraphs': ['殿上衮衣明日月，砚中旗影动龙蛇。', '纵横礼乐三千字，独对丹墀日未斜。']}]}, {'chapter': '咏华清宫', 'author': '（唐）王建', 'paragraphs': ['行尽江南数十程，晓风残月入华清。', '朝元阁上西风急，都入长杨作雨声。']}, {'chapter': '清平调词', 'author': '（唐）李白', 'paragraphs': ['云想衣裳花想容，春风拂槛露华浓。', '若非群玉山头见，会向瑶台月下逢。']}, {'chapter': '题邸间壁', 'author': '（宋）郑会', 'paragraphs': ['酴醿香梦怯春寒，翠掩重门燕子闲。', '敲断玉钗红烛冷，计程应说到常山。']}, {'chapter': '绝句', 'author': '（唐）杜甫', 'paragraphs': ['两个黄鹂鸣翠柳，一行白鹭上青天。', '窗含西岭千秋雪，门泊东吴万里船。']}, {'chapter': '海棠', 'author': '（宋）苏轼', 'paragraphs': ['东风袅袅泛崇光，香雾空蒙月转廊。', '只恐夜深花睡去，故烧高烛照红妆。']}, {'chapter': '清明', 'author': '（宋）王禹偁', 'paragraphs': ['无花无酒过清明，兴味萧然似野僧。', '昨日邻家乞新火，晓窗分与读书灯。']}, {'chapter': '清明', 'author': '（唐）杜牧', 'paragraphs': ['清明时节雨纷纷，路上行人欲断魂。', '借问酒家何处有，牧童遥指杏花村。']}, {'chapter': '社日', 'author': '（唐）张演', 'paragraphs': ['鹅湖山下稻粱肥，豚栅鸡栖对掩扉。', '桑柘影斜春社散，家家扶得醉人归。']}, {'chapter': '寒食', 'author': '（唐）韩翃', 'paragraphs': ['春城无处不飞花，寒食东风御柳斜。', '日暮汉宫传蜡烛，轻烟散入五侯家。']}, {'chapter': '江南春', 'author': '（唐）杜牧', 'paragraphs': ['千里莺啼绿映红，水村山郭酒旗风。', '南朝四百八十寺，多少楼台烟雨中。']}, {'chapter': '上高侍郎', 'author': '（唐）高蟾', 'paragraphs': ['天上碧桃和露种，日边红杏倚云栽。', '芙蓉生在秋江上，不向东风怨未开。']}, {'chapter': '绝句', 'author': '（宋）僧志安', 'paragraphs': ['古木阴中系短篷，杖藜扶我过桥东。', '沾衣欲湿杏花雨，吹面不寒杨柳风。']}, {'chapter': '游小园不值', 'author': '（宋）叶绍翁', 'paragraphs': ['应嫌屐齿印苍苔，十扣柴扉九不开。', '春色满园关不住，一枝红杏出墙来。']}, {'chapter': '客中行', 'author': '（唐）李白', 'paragraphs': ['兰陵美酒郁金香，玉碗盛来琥珀光。', '但使主人能醉客，不知何处是他乡。']}, {'chapter': '题屏', 'author': '（宋）刘季孙', 'paragraphs': ['呢喃燕子语梁间，底事来惊梦里闲。', '说与旁人浑不解，杖藜携酒看芝山。']}, {'chapter': '绝句漫兴', 'author': '（唐）杜甫', 'paragraphs': ['肠断春江欲尽头，杖藜徐步立芳洲。', '颠狂柳絮随风舞，轻薄桃花逐水流。']}, {'chapter': '庆全庵桃花', 'author': '（宋）谢枋得', 'paragraphs': ['寻得桃源好避秦，桃红又是一年春。', '花飞莫遣随流水，怕有渔郎来问津。']}, {'chapter': '玄都观桃花', 'author': '（唐）刘禹锡', 'paragraphs': ['紫陌红尘拂面来，无人不道看花回。', '玄都观里桃千树，尽是刘郎去后栽。']}, {'chapter': '再游玄都观', 'author': '（唐）刘禹锡', 'paragraphs': ['百亩庭中半是苔，桃花净尽菜花开。', '种桃道士归何处，前度刘郎今又来。']}, {'chapter': '滁州西涧', 'author': '（唐）韦应物', 'paragraphs': ['独怜幽草涧边生，上有黄鹂深树鸣。', '春潮带雨晚来急，野渡无人舟自横。']}, {'chapter': '花影', 'author': '（宋）苏轼', 'paragraphs': ['重重叠叠上瑶台，几度呼童扫不开。', '刚被太阳收拾去，却教明月送将来。']}, {'chapter': '北山', 'author': '（宋）王安石', 'paragraphs': ['北山输绿涨横陂，直堑回塘滟滟时。', '细数落花因坐久，缓寻芳草得归迟。']}, {'chapter': '湖上', 'author': '（宋）徐元杰', 'paragraphs': ['花开红树乱莺啼，草长平湖白鹭飞。', '风日晴和人意好，夕阳箫鼓几船归。']}, {'chapter': '漫兴', 'author': '（唐）杜甫', 'paragraphs': ['糁径杨花铺白毡，点溪荷叶叠青钱。', '笋根稚子无人见，沙上凫雏傍母眠。']}, {'chapter': '春晴', 'author': '（宋）王驾', 'paragraphs': ['雨前初见花间蕊，雨后全无叶底花。', '蜂蝶纷纷过墙去，却疑春色在邻家。']}, {'chapter': '春暮', 'author': '（宋）曹豳', 'paragraphs': ['门外无人问落花，绿阴冉冉遍天涯。', '林莺啼到无声处，青草池塘独听蛙。']}, {'chapter': '落花', 'author': '（宋）朱淑贞', 'paragraphs': ['连理枝头花正开，妒花风雨便相催。', '愿教青帝常为主，莫遣纷纷点翠苔。']}, {'chapter': '春暮游小园', 'author': '（宋）王淇', 'paragraphs': ['一从梅粉褪残妆，涂抹新红上海棠。', '开到荼蘼花事了，丝丝天棘出莓墙。']}, {'chapter': '莺梭', 'author': '（宋）刘克庄', 'paragraphs': ['掷柳迁乔太有情，交交时作弄机声。', '洛阳三月花如锦，多少工夫织得成。']}, {'chapter': '暮春即事', 'author': '（宋）叶采', 'paragraphs': ['双双瓦雀行书案，点点杨花入砚池。', '闲坐小窗读周易，不知春去几多时。']}, {'chapter': '登山', 'author': '（唐）李涉', 'paragraphs': ['终日昏昏醉梦间，忽闻春尽强登山。', '因过竹院逢僧话，又得浮生半日闲。']}, {'chapter': '蚕妇吟', 'author': '（唐）谢枋得', 'paragraphs': ['子规啼彻四更时，起视蚕稠怕叶稀。', '不信楼头杨柳月，玉人歌舞未曾归。']}, {'chapter': '晚春', 'author': '（唐）韩愈', 'paragraphs': ['草树知春不久归，百般红紫斗芳菲。', '杨花榆荚无才思，惟解漫天作雪飞。']}, {'chapter': '伤春', 'author': '（宋）杨万里', 'paragraphs': ['准拟今春乐事浓，依然枉却一东风。', '年年不带看花眼，不是愁中即病中。']}, {'chapter': '送春', 'author': '（宋）王令', 'paragraphs': ['三月残花落更开，小檐日日燕飞来。', '子规夜半犹啼血，不信东风唤不回。']}, {'chapter': '三月晦日送春', 'author': '（唐）贾岛', 'paragraphs': ['三月正当三十日，风光别我苦吟身。', '共君今夜不须睡，未到晓钟犹是春。']}, {'chapter': '客中初夏', 'author': '（宋）司马光', 'paragraphs': ['四月清和雨乍晴，南山当户转分明。', '更无柳絮因风起，惟有葵花向日倾。']}, {'chapter': '有约', 'author': '（宋）司马光', 'paragraphs': ['黄梅时节家家雨，青草池塘处处蛙。', '有约不来过夜半，闲敲棋子落灯花。']}, {'chapter': '初夏睡起', 'author': '（宋）杨万里', 'paragraphs': ['梅子流酸溅齿牙，芭蕉分绿上窗纱。', '日长睡起无情思，闲看儿童捉柳花。']}, {'chapter': '三衢道中', 'author': '（宋）曾几', 'paragraphs': ['梅子黄时日日晴，小溪泛尽却山行。', '绿阴不减来时路，添得黄鹂四五声。']}, {'chapter': '即景', 'author': '（宋）朱淑贞', 'paragraphs': ['竹摇清影罩幽窗，两两时禽噪夕阳。', '谢却海棠飞尽絮，困人天气日初长。']}, {'chapter': '夏日', 'author': '（宋）戴敏', 'paragraphs': ['乳鸭池塘水浅深，熟梅天气半晴阴。', '东园载酒西园醉，摘尽枇杷一树金。']}, {'chapter': '晚楼闲坐', 'author': '（宋）王安石', 'paragraphs': ['四顾山光接水光，凭栏十里芰荷香。', '清风明月无人管，并作南来一味凉。']}, {'chapter': '山居夏日', 'author': '（唐）高骈', 'paragraphs': ['绿树阴浓夏日长，楼台倒影入池塘。', '水晶帘动微风起，满架蔷薇一院香。']}, {'chapter': '田家', 'author': '（宋）范成大', 'paragraphs': ['昼出耘田夜绩麻，村庄儿女各当家。', '童孙未解供耕织，也傍桑阴学种瓜。']}, {'chapter': '村居即事', 'author': '（宋）范成大', 'paragraphs': ['绿遍山原白满川，子规声里雨如烟。', '乡村四月闲人少，才了蚕桑又插田。']}, {'chapter': '题榴花', 'author': '（宋）朱熹', 'paragraphs': ['五月榴花照眼明，枝间时见子初成。', '可怜此地无车马，颠倒苍苔落绛英。']}, {'chapter': '村晚', 'author': '（宋）雷震', 'paragraphs': ['草满池塘水满陂，山衔落日浸寒漪。', '牧童归去横牛背，短笛无腔信口吹。']}, {'chapter': '茅檐', 'author': '（宋）王安石', 'paragraphs': ['茅檐常扫净无苔，花木成蹊手自栽。', '一水护田将绿绕，两山排闼送青来。']}, {'chapter': '乌衣巷', 'author': '（唐）刘禹锡', 'paragraphs': ['朱雀桥边野草花，乌衣巷口夕阳斜。', '旧时王谢堂前燕，飞入寻常百姓家。']}, {'chapter': '送元二使安西', 'author': '（唐）王维', 'paragraphs': ['渭城朝雨浥轻尘，客舍青青柳色新。', '劝君更尽一杯酒，西出阳关无故人。']}, {'chapter': '与史朗中饮听黄鹤楼上吹笛', 'author': '（唐）李白', 'paragraphs': ['一为迁客去长沙，西望长安不见家。', '黄鹤楼中吹玉笛，江城五月落梅花。']}, {'chapter': '题淮南寺', 'author': '（宋）程颢', 'paragraphs': ['南去北来休便休，白苹吹尽楚江秋。', '道人不是悲秋客，一任晚山相对愁。']}, {'chapter': '秋月', 'author': '（宋）程颢', 'paragraphs': ['清溪流过碧山头，空水澄鲜一色秋。', '隔断红尘三十里，白云红叶两悠悠。']}, {'chapter': '七夕', 'author': '（宋）杨朴', 'paragraphs': ['未会牵牛意若何，须邀织女弄金梭。', '年年乞与人间巧，不道人间巧已多。']}, {'chapter': '立秋', 'author': '（宋）刘翰', 'paragraphs': ['乳鸦啼散玉屏空，一枕新凉一扇风。', '睡起秋声无觅处，满阶梧叶月明中。']}, {'chapter': '秋夕', 'author': '（唐）杜牧', 'paragraphs': ['银烛秋光冷画屏，轻罗小扇扑流萤。', '天街夜色凉如水，卧看牵牛织女星。']}, {'chapter': '中秋月', 'author': '（唐）杜牧', 'paragraphs': ['暮云收尽溢清寒，银汉无声转玉盘。', '此生此夜不长好，明月明年何处看？']}, {'chapter': '江楼有感', 'author': '（唐）赵嘏', 'paragraphs': ['独上江楼思渺然，月光如水水如天。', '同来玩月人何在，风景依稀似去年。']}, {'chapter': '题临安邸', 'author': '（宋）林升', 'paragraphs': ['山外青山楼外楼，西湖歌舞几时休。', '暖风薰得游人醉，直把杭州作汴州。']}, {'chapter': '西湖', 'author': '（宋）苏轼', 'paragraphs': ['毕竟西湖六月中，风光不与四时同。', '接天莲叶无穷碧，映日荷花别样红。']}, {'chapter': '饮湖上初晴后雨', 'author': '（宋）苏轼', 'paragraphs': ['水光潋滟晴方好，山色空蒙雨亦奇。', '欲把西湖比西子，淡妆浓抹总相宜。']}, {'chapter': '入直召对选德殿赐茶而退', 'author': '（宋）周必大', 'paragraphs': ['绿槐夹道集昏鸦，敕使传宣坐赐茶。', '归到玉堂清不寐，月钩初上紫薇花。']}, {'chapter': '夏日登车盖亭', 'author': '（宋）蔡确', 'paragraphs': ['纸屏石枕竹方床，手倦抛书午梦长。', '睡起莞然成独笑，数声渔笛在沧浪。']}, {'chapter': '真玉堂作', 'author': '（宋）洪咨夔', 'paragraphs': ['禁门深锁寂无哗，浓墨淋漓两相麻。', '唱彻五更天未晓，一墀月浸紫薇花。']}, {'chapter': '竹楼', 'author': '（唐）李嘉佑', 'paragraphs': ['傲吏身闲笑五侯，西江取竹起高楼。', '南风不用蒲葵扇，纱帽闲眠对水鸥。']}, {'chapter': '直中书省', 'author': '（唐）白居易', 'paragraphs': ['丝纶阁下文章静，钟鼓楼中刻漏长。', '独坐黄昏谁是伴，紫薇花对紫薇郎。']}, {'chapter': '观书有感（其一）', 'author': '（宋）朱熹', 'paragraphs': ['半亩方塘一鉴开，天光云影共徘徊。', '问渠那得清如许，为有源头活水来。']}, {'chapter': '泛舟', 'author': '（宋）朱熹', 'paragraphs': ['昨夜江边春水生，艨艟巨舰一毛轻。', '向来枉费推移力，此日中流自在行。']}, {'chapter': '冷泉亭', 'author': '（宋）林稹', 'paragraphs': ['一泓清可沁诗脾，冷暖年来只自知。', '流出西湖载歌舞，回头不似在山时。']}, {'chapter': '冬景', 'author': '（宋）苏轼', 'paragraphs': ['荷尽已无擎雨盖，菊残犹有傲霜枝。', '一年好景君须记，最是橙黄橘绿时。']}, {'chapter': '枫桥夜泊', 'author': '（唐）张继', 'paragraphs': ['月落乌啼霜满天，江枫渔火对愁眠。', '姑苏城外寒山寺，夜半钟声到客船。']}, {'chapter': '寒夜', 'author': '（宋）杜小山', 'paragraphs': ['寒夜客来茶当酒，竹炉汤沸火初红。', '寻常一样窗前月，才有梅花便不同。']}, {'chapter': '霜月', 'author': '（唐）李商隐', 'paragraphs': ['初闻征雁已无蝉，百尺楼台水接天。', '青女素娥俱耐冷，月中霜里斗婵娟。']}, {'chapter': '梅', 'author': '（宋）王淇', 'paragraphs': ['不受尘埃半点侵，竹篱茅舍自甘心。', '只因误识林和靖，惹得诗人说到今。']}, {'chapter': '早春', 'author': '（宋）白玉蟾', 'paragraphs': ['南枝才放两三花，雪里吟香弄粉些。', '淡淡著烟浓著月，深深笼水浅笼沙。']}, {'chapter': '雪梅', 'author': '（宋）卢梅坡', 'paragraphs': [{'subchapter': '其一', 'paragraphs': ['梅雪争春未肯降，骚人阁笔费评章。', '梅须逊雪三分白，雪却输梅一段香。']}, {'subchapter': '其二', 'paragraphs': ['有梅无雪不精神，有雪无诗俗了人。', '日暮诗成天又雪，与梅井作十分春。']}]}, {'chapter': '答钟弱翁', 'author': '（宋）牧童', 'paragraphs': ['草铺横野六七里，笛弄晚风三四声。', '归来饱饭黄昏后，不脱蓑衣卧月明。']}, {'chapter': '秦淮夜泊', 'author': '（唐）杜牧', 'paragraphs': ['烟笼寒水月笼沙，夜泊秦淮近酒家。', '商女不知亡国恨，隔江犹唱后庭花。']}, {'chapter': '归雁', 'author': '（唐）钱起', 'paragraphs': ['潇湘何事等闲回，水碧沙明两岸苔。', '二十五弦弹夜月，不胜清怨却飞来。']}, {'chapter': '题壁', 'author': '无名氏', 'paragraphs': ['一团茅草乱蓬蓬，蓦地烧天蓦地空。', '争似满炉煨榾柮，漫腾腾地暖烘烘。']}]}
{'type': '七言律诗', 'content': [{'chapter': '早朝大明宫', 'author': '（唐）贾至', 'paragraphs': ['银烛朝天紫陌长，禁城春色晓苍苍。', '千条弱柳垂青琐，百啭流莺绕建章。', '剑佩声随玉墀步，衣冠身惹御炉香。', '共沐恩波凤池上，朝朝染翰侍君王。']}, {'chapter': '和贾舍人早朝', 'author': '（唐）杜甫', 'paragraphs': ['五夜漏声催晓箭，九重春色醉仙桃。', '旌旗日暖龙蛇动，宫殿风微燕雀高。', '朝罢香烟携满袖，诗成珠玉在挥毫。', '欲知世掌丝纶美，池上于今有凤毛。']}, {'chapter': '和贾舍人早朝', 'author': '（唐）王维', 'paragraphs': ['绛帻鸡人报晓筹，尚衣方进翠云裘。', '九天阊阖开宫殿，万国衣冠拜冕旒。', '日色才临仙掌动，香烟欲傍衮龙浮。', '朝罢须裁五色诏，佩声归到凤池头。']}, {'chapter': '和贾舍人早朝', 'author': '（唐）岑参', 'paragraphs': ['鸡鸣紫陌曙光寒，莺啭皇州春色阑。', '金阙晓钟开万户，玉阶仙仗拥千官。', '花迎剑佩星初落，柳拂旌旗露未干。', '独有凤凰池上客，阳春一曲和皆难。']}, {'chapter': '上元应制', 'author': '（宋）蔡襄', 'paragraphs': ['高列千峰宝炬森，端门方喜翠华临。', '宸游不为三元夜，乐事还同万众心。', '天上清光留此夕，人间和气阁春阴。', '要知尽庆华封祝，四十余年惠爱深。']}, {'chapter': '上元应制', 'author': '（宋）王淇', 'paragraphs': ['雪消华月满仙台，万烛当楼宝扇开。', '双凤云中扶辇下，六鳌海上驾山来。', '镐京春酒沾周宴，汾水秋风陋汉才。', '一曲升平人尽乐，君王又进紫霞杯。']}, {'chapter': '侍宴', 'author': '（唐）沈佺期', 'paragraphs': ['皇家贵主好神仙，别业初开云汉边。', '山出尽如鸣凤岭，池成不让饮龙川。', '妆楼翠幌教春住，舞阁金铺借日悬。', '敬从乘舆来此地，称觞献寿乐钧天。']}, {'chapter': '答丁元珍', 'author': '（宋）欧阳修', 'paragraphs': ['春风疑不到天涯，二月山城未见花。', '残雪压枝犹有橘，冻雷惊笋欲抽芽。', '夜闻啼雁生乡思，病入新年感物华。', '曾是洛阳花下客，野芳虽晚不须嗟。']}, {'chapter': '插花吟', 'author': '（宋）邵雍', 'paragraphs': ['头上花枝照酒卮，酒卮中有好花枝。', '身经两世太平日，眼见四朝全盛时。', '况复筋骸粗康健，那堪时节正芳菲。', '酒涵花影红光溜，争忍花前不醉归。']}, {'chapter': '寓意', 'author': '（宋）晏殊', 'paragraphs': ['油壁香车不再逢，峡云无迹任西东。', '梨花院落溶溶月，柳絮池塘淡淡风。', '几日寂寥伤酒后，一番萧瑟禁烟中。', '鱼书欲寄何由达，水远山长处处同。']}, {'chapter': '寒食书事', 'author': '（宋）赵鼎', 'paragraphs': ['寂寂柴门村落里，也教插柳纪年华。', '禁烟不到粤人国，上冢亦携庞老家。', '汉寝唐陵无麦饭，山溪野径有梨花。', '一樽竟藉青苔卧，莫管城头奏暮笳。']}, {'chapter': '清明', 'author': '（宋）黄庭坚', 'paragraphs': ['佳节清明桃李笑，野田荒冢只生愁。', '雷惊天地龙蛇蛰，雨足郊原草木柔。', '人乞祭余骄妾妇，士甘焚死不公侯。', '贤愚千载知谁是，满眼蓬蒿共一丘。']}, {'chapter': '清明', 'author': '（宋）高菊卿', 'paragraphs': ['南北山头多墓田，清明祭扫各纷然。', '纸灰飞作白蝴蝶，泪血染成红杜鹃。', '日落狐狸眠冢上，夜归儿女笑灯前。', '人生有酒须当醉，一滴何曾到九泉。']}, {'chapter': '郊行即事', 'author': '（宋）程颢', 'paragraphs': ['芳原绿野恣行时，春入遥山碧四围。', '兴逐乱红穿柳巷，困临流水坐苔矶。', '莫辞盏酒十分劝，只恐风花一片飞。', '况是清明好天气，不妨游衍莫忘归。']}, {'chapter': '秋千', 'author': '（宋）僧惠洪', 'paragraphs': ['画架双裁翠络偏，佳人春戏小楼前。', '飘扬血色裙拖地，断送玉容人上天。', '花板润沾红杏雨，彩绳斜挂绿杨烟。', '下来闲处从容立，疑是蟾宫谪神仙。']}, {'chapter': '曲江对酒', 'author': '（唐）杜甫', 'paragraphs': [{'subchapter': '其一', 'paragraphs': ['一片花飞减却春，风飘万点正愁人。', '且看欲尽花经眼，莫厌伤多酒入唇。', '江上小堂巢翡翠，苑边高冢卧麒麟。', '细推物理须行乐，何用浮名绊此身。']}, {'subchapter': '其二', 'paragraphs': ['朝回日日典春衣，每日江头尽醉归。', '酒债寻常行处有，人生七十古来稀。', '穿花蛱蝶深深见，点水蜻蜓款款飞。', '传与风光共流转，暂时相赏莫相违。']}]}, {'chapter': '黄鹤楼', 'author': '（唐）崔颢', 'paragraphs': ['昔人已乘黄鹤去，此地空余黄鹤楼。', '黄鹤一去不复返，白云千载空悠悠。', '晴川历历汉阳树，芳草萋萋鹦鹉州。', '日暮乡关何处是，烟波江上使人愁。']}, {'chapter': '旅怀', 'author': '（唐）崔涂', 'paragraphs': ['水流花谢两无情，送尽东风过楚城。', '蝴蝶梦中家万里，杜鹃枝上月三更。', '故园书动经年绝，华发春催两鬓生。', '自是不归归便得，五湖烟景有谁争。']}, {'chapter': '答李儋', 'author': '（唐）韦应物', 'paragraphs': ['去年花里逢君别，今日花开又一年。', '世事茫茫难自料，春愁黯黯独成眠。', '身多疾病思田里，邑有流亡愧俸钱。', '闻道欲来相问讯，西楼望月几回圆。']}, {'chapter': '江村', 'author': '（唐）杜甫', 'paragraphs': ['清江一曲抱村流，长夏江村事事幽。', '自去自来梁上燕，相亲相近水中鸥。', '老妻画纸为棋局，稚子敲针作钓钩。', '多病所须惟药物，微躯此外更何求。']}, {'chapter': '夏日', 'author': '（宋）张文潜', 'paragraphs': ['长夏江村风日清，檐牙燕雀已生成。', '蝶衣晒粉花枝午，蛛网添丝屋角晴。', '落落疏帘邀月影，嘈嘈虚枕纳溪声。', '久斑两鬓如霜雪，直欲樵渔过此生。']}, {'chapter': '积雨辋川庄作', 'author': '（唐）王维', 'paragraphs': ['积雨空林烟火迟，蒸藜炊黍饷东菑。', '漠漠水田飞白鹭，阴阴夏木啭黄鹂。', '山中习静观朝槿，松下清斋折露葵。', '野老与人争席罢，海鸥何事更相疑。']}, {'chapter': '新竹', 'author': '（宋）陆游', 'paragraphs': ['插棘编篱谨护持，养成寒碧映涟漪。', '清风掠地秋先到，赤日行天午不知。', '解箨时闻声簌簌，放梢初见影离离。', '官闲我欲频来此，枕簟仍教到处随。']}, {'chapter': '偶成', 'author': '（宋）程颢', 'paragraphs': ['闲来无事不从容，睡觉东窗日已红。', '万物静观皆自得，四时佳兴与人同。', '道通天地有形外，思入风云变态中。', '富贵不淫贫贱乐，男儿到此是豪雄。']}, {'chapter': '表兄话旧', 'author': '（唐）窦叔向', 'paragraphs': ['夜合花开香满庭，夜深微雨醉初醒。', '远书珍重何由达，旧事凄凉不可听。', '去日儿童皆长大，昔年亲友半凋零。', '明朝又是孤舟别，愁见河桥酒幔青。']}, {'chapter': '游月陂', 'author': '（宋）程颢', 'paragraphs': ['月陂堤上四徘徊，北有中天百尺台。', '万物已随秋气改，一樽聊为晚凉开。', '水心云影闲相照，林下泉声静自来。', '世事无端何足计，但逢佳节约重陪。']}, {'chapter': '秋兴八首', 'author': '（唐）杜甫', 'paragraphs': [{'subchapter': '其一', 'paragraphs': ['千家山郭静朝晖，日日江楼坐翠微。', '信宿渔人还泛泛，清秋燕子故飞飞。', '匡衡抗疏功名薄，刘向传经心事违。', '同学少年多不贱，五陵裘马自轻肥。']}, {'subchapter': '其二', 'paragraphs': ['蓬莱宫阙对南山，承露金茎霄汉间。', '西望瑶池降王母，东来紫气满函关。', '云移雉尾开宫扇，日绕龙鳞识圣颜。', '一卧沧江惊岁晚，几回青琐点朝班。']}, {'subchapter': '其三', 'paragraphs': ['玉露凋伤枫树林，巫山巫峡气萧森。', '江间波浪兼天涌，塞上风云接地阴。', '丛菊两开他日泪，孤舟一系故园心。', '寒衣处处催刀尺，白帝城高急暮砧。']}, {'subchapter': '其四', 'paragraphs': ['昆明池水汉时功，武帝旌旗在眼中。', '织女机丝虚夜月，石鲸鳞甲动秋风。', '波飘菰米沉云黑，露冷莲房坠粉红。', '关塞极天惟鸟道，江湖满地一渔翁。']}]}, {'chapter': '月夜舟中', 'author': '（宋）戴复古', 'paragraphs': ['满船明月浸虚空，绿水无痕夜气冲。', '诗思浮沈樯影里，梦魂摇拽橹声中。', '星辰冷落碧潭水，鸿雁悲鸣红蓼风。', '数点渔灯依古岸，断桥垂露滴梧桐。']}, {'chapter': '长安秋望', 'author': '（唐）赵嘏', 'paragraphs': ['云物凄凉拂曙流，汉家宫阙动高秋。', '残星几点雁横塞，长笛一声人倚楼。', '紫艳半开篱菊静，红衣落尽渚莲愁。', '鲈鱼正美不归去，空戴南冠学楚囚。']}, {'chapter': '新秋', 'author': '（唐）杜甫', 'paragraphs': ['火云犹未敛奇峰，欹枕初惊一叶风。', '几处园林萧瑟里，谁家砧杵寂寥中。', '蝉声断续悲残月，萤焰高低照暮空。', '赋就金门期再献，夜深搔首叹飞蓬。']}, {'chapter': '中秋', 'author': '（宋）李朴', 'paragraphs': ['皓魄当空宝镜升，云间仙籁寂无声。', '平分秋色一轮满，长伴云衢千里明。', '狡兔空从弦外落，妖蟆休向眼前生。', '灵槎拟约同携手，更待银河澈底清。']}, {'chapter': '九日蓝耕会饮', 'author': '（唐）杜甫', 'paragraphs': ['老去悲秋强自宽，兴来今日尽君欢。', '羞将短发还吹帽，笑倩旁人为正冠。', '蓝水远从千涧落，玉山高并两峰寒。', '明年此会知谁健，醉把茱萸仔细看。']}, {'chapter': '秋思', 'author': '（宋）陆游', 'paragraphs': ['利欲驱人万火牛，江湖浪迹一沙鸥。', '日长似岁闲方觉，事大如天醉亦休。', '砧杵敲残深巷月，梧桐摇落故园秋。', '欲舒老眼无高处，安得元龙百尺楼。']}, {'chapter': '与朱山人', 'author': '（唐）杜甫', 'paragraphs': ['锦里先生乌角巾，园收芋栗未全贫。', '惯看宾客儿童喜，得食阶除鸟雀驯。', '秋水才深四五尺，野航恰受两三人。', '白沙翠竹江村暮，相送柴门月色新。']}, {'chapter': '闻笛', 'author': '（唐）赵嘏', 'paragraphs': ['谁家吹笛画楼中，断续声随断续风。', '响遏行云横碧落，清和冷月到帘栊。', '兴来三弄有桓子，赋就一篇怀马融。', '曲罢不知人在否，余音嘹亮尚飘空。']}, {'chapter': '冬景', 'author': '（宋）刘克庄', 'paragraphs': ['晴窗早觉爱朝曦，竹外秋声渐作威。', '命仆安排新暖阁，呼童熨贴旧寒衣。', '叶浮嫩绿酒初熟，橙切香黄蟹正肥。', '蓉菊满园皆可羡，赏心从此莫相违。']}, {'chapter': '冬至', 'author': '（唐）杜甫', 'paragraphs': ['天时人事日相催，冬至阳生春又来。', '刺绣五纹添弱线，吹葭六管动飞灰。', '岸容待腊将舒柳，山意冲寒欲放梅。', '云物不殊乡国异，教儿且覆掌中杯。']}, {'chapter': '梅花', 'author': '（宋）林逋', 'paragraphs': ['众芳摇落独鲜妍，占断风情向小园。', '疏影横斜水清浅，暗香浮动月黄昏。', '霜禽欲下先偷眼，粉蝶如知合断魂。', '幸有微吟可相狎，不须檀板共金樽。']}, {'chapter': '左迁至蓝关示侄孙湘', 'author': '（唐）韩愈', 'paragraphs': ['一封朝奏九重天，夕贬潮阳路八千。', '本为圣朝除弊政，敢将衰朽惜残年。', '云横秦岭家何在，雪拥蓝关马不前。', '知汝远来应有意，好收吾骨瘴江边。']}, {'chapter': '干戈', 'author': '（宋）王中', 'paragraphs': ['干戈未定欲何之，一事无成两鬓丝。', '踪迹大纲王粲传，情怀小样杜陵诗。', '鹡鸰音断人千里，乌鹊巢寒月一枝。', '安得中山千日酒，酩然直到太平时。']}, {'chapter': '归隐', 'author': '（宋）陈抟', 'paragraphs': ['十年踪迹走红尘，回首青山入梦频。', '紫绶纵荣争及睡，朱门虽富不如贫。', '愁闻剑戟扶危主，闷听笙歌聒醉人。', '携取旧书归旧隐，野花啼鸟一般春。']}, {'chapter': '山中寡妇', 'author': '（唐）杜荀鹤', 'paragraphs': ['夫因兵乱守蓬茅，麻苎裙衫鬓发焦。', '桑柘废来犹纳税，田园荒尽尚征苗。', '时挑野菜和根煮，旋砍生柴带叶烧。', '任是深山最深处，也应无计避征徭。']}, {'chapter': '送天师', 'author': '（明）朱权', 'paragraphs': ['霜落芝城柳影疏，殷勤送客出鄱湖。', '黄金甲锁雷霆印，红锦韬缠日月符。', '天上晓行骑只鹤，人间夜宿解双凫。', '匆匆归到神仙府，为问蟠桃熟也无。']}, {'chapter': '送毛伯温', 'author': '（明）明世宗', 'paragraphs': ['大将南征胆气豪，腰横秋水雁翎刀。', '风吹鼍鼓山河动，电闪旌旗日月高。', '天上麒麟原有种，穴中蝼蚁岂能逃。', '太平待诏归来日，朕与先生解战袍。']}]}

