{'type': '五言絕句', 'content': [{'chapter': '春眠', 'author': '（唐）孟浩然', 'paragraphs': ['春眠不覺曉，處處聞啼鳥。', '夜來風雨聲，花落知多少。']}, {'chapter': '訪袁拾遺不遇', 'author': '（唐）孟浩然', 'paragraphs': ['洛陽訪才子，江嶺作流人。', '聞說梅花早，何如此地春。']}, {'chapter': '送郭司倉', 'author': '（唐）王昌齡', 'paragraphs': ['映門淮水綠，留騎主人心。', '明月隨良掾，春潮夜夜深。']}, {'chapter': '洛陽道', 'author': '（唐）儲光羲', 'paragraphs': ['大道直如發，春來佳氣多。', '五陵貴公子，雙雙鳴玉珂。']}, {'chapter': '獨坐敬亭山', 'author': '（唐）李白', 'paragraphs': ['衆鳥高飛盡，孤雲獨去閒。', '相看兩不厭，只有敬亭山。']}, {'chapter': '登鸛雀樓', 'author': '（唐）王之渙', 'paragraphs': ['白日依山盡，黃河入海流。', '欲窮千里目，更上一層樓。']}, {'chapter': '觀永樂公主入番', 'author': '（唐）孫逖', 'paragraphs': ['邊地鶯花少，年來未覺新。', '美人天上落，龍塞始應春。']}, {'chapter': '伊州歌', 'author': '（唐）金昌緒', 'paragraphs': ['打起黃鶯兒，莫教枝上啼。', '啼時驚妾夢，不得到遼西。']}, {'chapter': '左掖梨花', 'author': '（唐）丘爲', 'paragraphs': ['冷豔全欺雪，餘香乍入衣。', '春風且莫定，吹向玉階飛。']}, {'chapter': '思君恩', 'author': '（唐）令狐楚', 'paragraphs': ['小苑鶯歌歇，長門蝶舞多。', '眼看春又去，翠輦不曾過。']}, {'chapter': '題袁氏別業', 'author': '（唐）賀知章', 'paragraphs': ['主人不相識，偶坐爲林泉。', '莫謾愁沽酒，囊中自有錢。']}, {'chapter': '夜送趙縱', 'author': '（唐）楊炯', 'paragraphs': ['趙氏連城璧，由來天下傳。', '送君還舊府，明月滿前川。']}, {'chapter': '竹裏館', 'author': '（唐）王維', 'paragraphs': ['獨坐幽篁裏，彈琴復長嘯。', '深林人不知，明月來相照。']}, {'chapter': '送朱大入秦', 'author': '（唐）王維', 'paragraphs': ['避人五陵去，寶劍值千金。', '分手脫相贈，平生一片心。']}, {'chapter': '長幹行', 'author': '（唐）崔顥', 'paragraphs': ['君家在何處？妾住在橫塘。', '停船暫借問，或恐是同鄉。']}, {'chapter': '詠史', 'author': '（唐）高適', 'paragraphs': ['尚有綈袍贈，應憐範叔寒。', '不知天下士，猶作布衣看。']}, {'chapter': '罷相作', 'author': '（唐）李適之', 'paragraphs': ['避賢初罷相，樂聖且銜杯。', '爲問門前客，今朝幾個來。']}, {'chapter': '逢俠者', 'author': '（唐）錢起', 'paragraphs': ['燕趙悲歌士，相逢劇孟家。', '寸心言不盡，前路日將斜。']}, {'chapter': '江行望匡廬', 'author': '（唐）錢起', 'paragraphs': ['咫尺愁風雨，匡廬不可登。', '只疑雲霧窟，猶有六朝僧。']}, {'chapter': '答李浣', 'author': '（唐）韋應物', 'paragraphs': ['林中觀易罷，溪上對鷗閒。', '楚俗饒詞客，何人最往還。']}, {'chapter': '秋風引', 'author': '（唐）劉禹錫', 'paragraphs': ['何處秋風至，蕭蕭送雁羣。', '朝來入庭樹，孤客最先聞。']}, {'chapter': '秋夜寄丘員外', 'author': '（唐）韋應物', 'paragraphs': ['懷君屬秋夜，散步詠涼天。', '山空松子落，幽人應未眠。']}, {'chapter': '秋日', 'author': '（唐）耿湋', 'paragraphs': ['返照入閭巷，憂來誰共語。', '古道少人行，秋風動禾黍。']}, {'chapter': '秋日湖上', 'author': '（唐）薛瑩', 'paragraphs': ['落日五湖遊，煙波處處愁。', '浮沉千古事，誰與問東流。']}, {'chapter': '宮中題', 'author': '（唐）李昂', 'paragraphs': ['輦路生秋草，上林花滿枝。', '憑高何限意，無復侍臣知。']}, {'chapter': '汾上驚秋', 'author': '（唐）蘇頲', 'paragraphs': ['北風吹白雲，萬里渡河汾。', '心緒逢搖落，秋聲不可聞。']}, {'chapter': '尋隱者不遇', 'author': '（唐）賈島', 'paragraphs': ['松下問童子，言師採藥去。', '只在此山中，雲深不知處。']}, {'chapter': '蜀道後期', 'author': '（唐）張說', 'paragraphs': ['客心爭日月，來往預期程。', '秋風不相待，先至洛陽城。']}, {'chapter': '靜夜思', 'author': '（唐）李白', 'paragraphs': ['牀前明月光，疑是地上霜。', '舉頭望明月，低頭思故鄉。']}, {'chapter': '秋浦歌', 'author': '（唐）李白', 'paragraphs': ['白髮三千丈，緣愁似個長。', '不知明鏡裏，何處得秋霜。']}, {'chapter': '贈喬侍郎', 'author': '（唐）陳子昂', 'paragraphs': ['漢廷榮巧宦，雲閣薄邊功。', '可憐驄馬使，白首爲誰雄。']}, {'chapter': '答五陵太守', 'author': '（唐）王昌齡', 'paragraphs': ['仗劍行千里，微軀敢一言。', '曾爲大梁客，不負信陵恩。']}, {'chapter': '行軍九日思長安故園', 'author': '（唐）岑參', 'paragraphs': ['強欲登高去，無人送酒來。', '遙憐故園菊，應傍戰場開。']}, {'chapter': '婕妤怨', 'author': '（唐）皇甫冉', 'paragraphs': ['花枝出建章，鳳管發昭陽。', '借問承恩者，雙蛾幾許長？']}, {'chapter': '題竹林寺', 'author': '（唐）朱放', 'paragraphs': ['歲月人間促，煙霞此地多。', '殷勤竹林寺，更得幾回過？']}, {'chapter': '過三閭廟', 'author': '（唐）戴叔倫', 'paragraphs': ['沅湘流不盡，屈子怨何深！', '日暮秋風起，蕭蕭楓樹林。']}, {'chapter': '易水送別', 'author': '（唐）駱賓王', 'paragraphs': ['此地別燕丹，壯士發衝冠。', '昔時人已沒，今日水猶寒。']}, {'chapter': '別盧秦卿', 'author': '（唐）司空曙', 'paragraphs': ['知有前期在，難分此夜中。', '無將故人酒，不及石尤風。']}, {'chapter': '答人', 'author': '（唐）太上隱者', 'paragraphs': ['偶來松樹下，高枕石頭眠。', '山中無曆日，寒盡不知年。']}]}
{'type': '五言律詩', 'content': [{'chapter': '幸蜀回至劍門', 'author': '（唐）李隆基', 'paragraphs': ['劍閣橫雲峻，鑾輿出狩回。', '翠屏千仞合，丹嶂五丁開。', '灌木縈旗轉，仙雲拂馬來。', '乘時方在德，嗟爾勒銘才。']}, {'chapter': '和晉陵陸承相', 'author': '（唐）杜審言', 'paragraphs': ['獨有宦遊人，偏驚物候新。', '雲霞出海曙，梅柳渡江春。', '淑氣催黃鳥，晴光轉綠蘋。', '忽聞歌古調，歸思欲沾巾。']}, {'chapter': '蓬萊三殿侍宴奉敕詠終南山', 'author': '（唐）杜審言', 'paragraphs': ['北斗掛城邊，南山倚殿前。', '雲標金闕迥，樹杪玉堂懸。', '半嶺通佳氣，中峯繞瑞煙。', '小臣持獻壽，長此戴堯天。']}, {'chapter': '春夜別友人', 'author': '（唐）陳子昂', 'paragraphs': ['銀燭吐青煙，金尊對綺筵。', '離堂思琴瑟，別路繞山川。', '明月隱高樹，長河沒曉天。', '悠悠洛陽道，此會在何年。']}, {'chapter': '長寧公主東莊侍宴', 'author': '（唐）李嶠', 'paragraphs': ['別業臨青甸，鳴鑾降紫霄。', '長筵鵷鷺集，仙管鳳凰調。', '樹接南山近，煙含北渚遙。', '承恩鹹已醉，戀賞未還鑣。']}, {'chapter': '恩賜麗正殿書院賜宴應制得林字', 'author': '（唐）張說', 'paragraphs': ['東壁圖書府，西園翰墨林。', '誦詩聞國政，講易見天心。', '位竊和羹重，恩叨醉酒深。', '載歌春興曲，情竭爲知音。']}, {'chapter': '送友人', 'author': '（唐）李白', 'paragraphs': ['青山橫北郭，白水繞東城。', '此地一爲別，孤篷萬里徵。', '浮雲遊子意，落日故人情。', '揮手自茲去，蕭蕭斑馬鳴。']}, {'chapter': '送友人入蜀', 'author': '（唐）李白', 'paragraphs': ['見說蠶叢路，崎嶇不易行。', '山從人面起，雲傍馬頭生。', '芳樹籠秦棧，春流繞蜀城。', '升沈應已定，不必問君平。']}, {'chapter': '次北固山下', 'author': '（唐）王灣', 'paragraphs': ['客路青山外，行舟綠水前。', '潮平兩岸闊，風正一帆懸。', '海日生殘夜，江春入舊年。', '鄉書何處達，歸雁洛陽邊。']}, {'chapter': '蘇氏別業', 'author': '（唐）祖詠', 'paragraphs': ['別業居幽處，到來生隱心。', '南山當戶牖，澧水映園林。', '竹覆經冬雪，庭昏未夕陰。', '寥寥人境外，閒坐聽春禽。']}, {'chapter': '春宿左省', 'author': '（唐）杜甫', 'paragraphs': ['花隱掖垣暮，啾啾棲鳥過。', '星臨萬戶動，月傍九霄多。', '不寢聽金鑰，因風想玉珂。', '明朝有封事，數問夜如何？']}, {'chapter': '題玄武禪師屋壁', 'author': '（唐）杜甫', 'paragraphs': ['何年顧虎頭，滿壁畫滄州。', '赤日石林氣，青天江海流。', '錫飛常近鶴，杯渡不驚鷗。', '似得廬山路，真隨惠遠遊。']}, {'chapter': '終南山', 'author': '（唐）王維', 'paragraphs': ['太乙近天都，連山到海隅。', '白雲回望合，青靄入看無。', '分野中峯變，陰晴衆壑殊。', '欲投人處宿，隔水問樵夫。']}, {'chapter': '登總持閣', 'author': '（唐）岑參', 'paragraphs': ['高閣逼諸天，登臨近日邊。', '晴開萬井樹，愁看五陵煙。', '檻外低秦嶺，窗中小渭川。', '早知清淨理，常願奉金仙。']}, {'chapter': '寄左省杜拾遺', 'author': '（唐）岑參', 'paragraphs': ['聯步趨丹陛，分曹限紫薇。', '曉隨天仗入，暮惹御香歸。', '白髮悲花落，青雲羨鳥飛。', '聖朝無闕事，自覺諫書稀。']}, {'chapter': '登兗州城樓', 'author': '（唐）杜甫', 'paragraphs': ['東郡趨庭日，南樓縱目初。', '浮雲連海岱，平野入青徐。', '孤嶂秦碑在，荒城魯殿餘。', '從來多古意，臨眺獨躊躇。']}, {'chapter': '杜少府之任蜀州', 'author': '（唐）王勃', 'paragraphs': ['城闕輔三秦，風煙望五津。', '與君離別意，同是宦遊人。', '海內存知己，天涯若比鄰。', '無爲在歧路，兒女共沾巾。']}, {'chapter': '送崔融', 'author': '（唐）杜審言', 'paragraphs': ['君王行出將，書記遠從徵。', '祖帳連河闕，軍麾動洛城。', '旌旗朝朔氣，笳吹夜邊聲。', '坐覺煙塵掃，秋風古北平。']}, {'chapter': '扈從登封途中作', 'author': '（唐）宋之問', 'paragraphs': ['帳殿鬱崔嵬，仙遊實壯哉！', '曉雲連幕卷，夜火雜星迴。', '谷暗千旗出，山鳴萬乘來。', '扈從良可賦，終乏掞天才。']}, {'chapter': '題義公禪房', 'author': '（唐）孟浩然', 'paragraphs': ['義公習禪寂，結宇依空林。', '戶外一峯秀，階前衆壑深。', '夕陽連雨足，空翠落庭陰。', '看取蓮花淨，方知不染心。']}, {'chapter': '醉後贈張九旭', 'author': '（唐）高適', 'paragraphs': ['世上漫相識，此翁殊不然。', '興來書自聖，醉後語尤顛。', '白髮老閒事，青雲在目前。', '牀頭一壺酒，能更幾回眠。']}, {'chapter': '玉臺觀', 'author': '（唐）高適', 'paragraphs': ['浩劫因王造，平臺訪古遊。', '彩雲蕭史駐，文字魯恭留。', '宮闕通羣帝，乾坤到十洲。', '人傳有笙鶴，時過北山頭。']}, {'chapter': '觀李固請司馬弟山水圖', 'author': '（唐）杜甫', 'paragraphs': ['方丈渾連水，天台總映雲。', '人間長見畫，老去恨空聞。', '范蠡舟偏小，王喬鶴不羣。', '此生隨萬物，何處出塵氛。']}, {'chapter': '旅夜書懷', 'author': '（唐）杜甫', 'paragraphs': ['細草微風岸，危檣獨夜舟。', '星垂平野闊，月涌大江流。', '名豈文章著，官因老病休。', '飄飄何所似，天地一沙鷗。']}, {'chapter': '登岳陽樓', 'author': '（唐）杜甫', 'paragraphs': ['昔聞洞庭水，今上岳陽樓。', '吳楚東南坼，乾坤日夜浮。', '親朋無一字，老病有孤舟。', '戎馬關山北，憑軒涕泗流。']}, {'chapter': '江南旅情', 'author': '（唐）祖詠', 'paragraphs': ['楚山不可極，歸路但蕭條。', '海色晴看雨，江聲夜聽潮。', '劍留南斗近，書寄北風遙。', '爲報空潭橘，無媒寄洛橋。']}, {'chapter': '宿龍興寺', 'author': '（唐）綦毋潛', 'paragraphs': ['香剎夜忘歸，鬆清古殿扉。', '燈明方丈室，珠系比丘衣。', '白日傳心淨，青蓮喻法微。', '天花落不盡，處處鳥銜飛。']}, {'chapter': '破山寺後禪院', 'author': '（唐）常建', 'paragraphs': ['清晨入古寺，初日照高林。', '曲徑通幽處，禪房花木深。', '山光悅鳥性，潭影空人心。', '萬籟此俱寂，惟聞鐘磬音。']}, {'chapter': '題鬆汀驛', 'author': '（唐）張佑', 'paragraphs': ['山色遠含空，蒼茫澤國東。', '海明先見日，江白迥聞風。', '鳥道高原去，人煙小徑通。', '那知舊遺逸，不在五湖中。']}, {'chapter': '聖果寺', 'author': '（唐）釋處默', 'paragraphs': ['路自中峯上，盤迴出薜蘿。', '到江吳地盡，隔岸越山多。', '古木叢青藹，遙天浸白波。', '下方城郭近，鐘磬雜笙歌。']}, {'chapter': '野望', 'author': '（唐）王績', 'paragraphs': ['東皋薄暮望，徙倚欲何依。', '樹樹皆秋色，山山惟落暉。', '牧人驅犢返，獵馬帶禽歸。', '相顧無相識，長歌懷采薇。']}, {'chapter': '送著作佐郎崔融等從樑王東征', 'author': '（唐）陳子昂', 'paragraphs': ['金天方肅殺，白露始專征。', '王師非樂戰，之子慎佳兵。', '海氣侵南部，邊風掃北平。', '莫賣盧龍塞，歸邀麟閣名。']}, {'chapter': '攜妓納涼晚際遇雨', 'author': '（唐）杜甫', 'paragraphs': [{'subchapter': '其一', 'paragraphs': ['落日放船好，輕風生浪遲。', '竹深留客處，荷淨納涼時。', '公子調冰水，佳人雪藕絲。', '片雲頭上黑，應是雨催詩。']}, {'subchapter': '其二', 'paragraphs': ['雨來沾席上，風急打船頭。', '越女紅裙溼，燕姬翠黛愁。', '纜侵堤柳系，幔捲浪花浮。', '歸路翻蕭颯，陂塘五月秋。']}]}, {'chapter': '宿雲門寺閣', 'author': '（唐）孫逖', 'paragraphs': ['香閣東山下，煙花象外幽。', '懸燈千嶂夕，卷幔五湖秋。', '畫壁餘鴻雁，紗窗宿斗牛。', '更疑天路近，夢與白雲遊。']}, {'chapter': '秋登宣城謝眺北樓', 'author': '（唐）李白', 'paragraphs': ['江城如畫裏，山晚望晴空。', '兩水夾明鏡，雙橋落彩虹。', '人煙寒橘柚，秋色老梧桐。', '誰念北樓上，臨風懷謝公。']}, {'chapter': '臨洞庭', 'author': '（唐）孟浩然', 'paragraphs': ['八月湖水平，涵虛混太清。', '氣蒸雲夢澤，波撼岳陽城。', '欲濟無舟楫，端居恥聖明。', '坐觀垂釣者，徒有羨魚情。']}, {'chapter': '過香積寺', 'author': '（唐）王維', 'paragraphs': ['不知香積寺，數裏入雲峯。', '古木無人徑，深山何處鐘。', '泉聲咽危石，日色冷青松。', '薄暮空潭曲，安禪製毒龍。']}, {'chapter': '送鄭侍御謫閩中', 'author': '（唐）高適', 'paragraphs': ['謫去君無恨，閩中我舊過。', '大都秋雁少，只是夜猿多。', '東路雲山合，南天瘴癘和。', '自當逢雨露，行矣慎風波。']}, {'chapter': '秦州雜詩', 'author': '（唐）杜甫', 'paragraphs': ['鳳林戈未息，魚海路常難。', '候火雲峯峻，懸軍幕井乾。', '風連西極動，月過北庭寒。', '故老思飛將，何時議築壇。']}, {'chapter': '禹廟', 'author': '（唐）杜甫', 'paragraphs': ['禹廟空山裏，秋風落日斜。', '荒庭垂橘柚，古屋畫龍蛇。', '雲氣生虛壁，江聲走白沙。', '早知乘四載，疏鑿控三巴。']}, {'chapter': '望秦川', 'author': '（唐）李頎', 'paragraphs': ['秦川朝望迥，日出正東峯。', '遠近山河淨，逶迤城闕重。', '秋聲萬戶竹，寒色五陵鬆。', '有客歸歟嘆，悽其霜露濃。']}, {'chapter': '同王徵君洞庭有懷', 'author': '（唐）張謂', 'paragraphs': ['八月洞庭秋，瀟湘水北流。', '還家萬里夢，爲客五更愁。', '不用開書帙，偏宜上酒樓。', '故人京洛滿，何日復同遊。']}, {'chapter': '渡揚子江', 'author': '（唐）丁仙芝', 'paragraphs': ['桂楫中流望，空波兩岸明。', '林開揚子驛，山出潤州城。', '海盡邊陰靜，江寒朔吹生。', '更聞楓葉下，淅瀝度秋聲。']}, {'chapter': '幽州夜歌', 'author': '（唐）張說', 'paragraphs': ['涼風吹夜雨，蕭瑟動寒林。', '正有高堂宴，能忘遲暮心。', '軍中宜劍舞，塞上重笳音。', '不作邊城將，誰知恩遇深。']}]}
{'type': '七言絕句', 'content': [{'chapter': '春日偶成', 'author': '（宋）程顥', 'paragraphs': ['雲淡風輕近午天，傍花隨柳過前川。', '時人不識餘心樂，將謂偷閒學少年。']}, {'chapter': '春日', 'author': '（宋）朱熹', 'paragraphs': ['勝日尋芳泗水濱，無邊光景一時新。', '等閒識得東風面，萬紫千紅總是春。']}, {'chapter': '春宵', 'author': '（宋）蘇軾', 'paragraphs': ['春宵一刻值千金，花有清香月有陰。', '歌管樓臺聲細細，鞦韆院落夜沈沈。']}, {'chapter': '城東早春', 'author': '（唐）楊巨源', 'paragraphs': ['詩家清景在新春，綠柳才黃半未勻。', '若待上林花似錦，出門俱是看花人。']}, {'chapter': '春夜', 'author': '（宋）王安石', 'paragraphs': ['金爐香燼漏聲殘，剪剪輕風陣陣寒。', '春色惱人眠不得，月移花影上欄杆。']}, {'chapter': '初春小雨', 'author': '（宋）韓愈', 'paragraphs': ['天街小雨潤如酥，草色遙看近卻無。', '最是一年春好處，絕勝煙柳滿皇都。']}, {'chapter': '元日', 'author': '（宋）王安石', 'paragraphs': ['爆竹聲中一歲除，春風送暖入屠蘇。', '千門萬戶曈曈日，總把新桃換舊符。']}, {'chapter': '上元侍宴', 'author': '（宋）蘇軾', 'paragraphs': ['淡月疏星繞建章，仙風吹下御爐香。', '侍臣鵠立通明殿，一朵紅雲捧玉皇。']}, {'chapter': '立春偶成', 'author': '（宋）張栻', 'paragraphs': ['律回歲晚冰霜少，春到人間草木知。', '便覺眼前生意滿，東風吹水綠參差。']}, {'chapter': '打球圖', 'author': '（宋）晁無咎', 'paragraphs': ['閶闔千門萬戶開，三郎沈醉打球回。', '九齡已老韓休死，無復明朝諫疏來。']}, {'chapter': '宮詞', 'author': '（宋）林洪', 'paragraphs': [{'subchapter': '其一', 'paragraphs': ['金殿當頭紫閣重，仙人掌上玉芙蓉。', '太平天子朝元日，五色雲車駕六龍。']}, {'subchapter': '其二', 'paragraphs': ['殿上袞衣明日月，硯中旗影動龍蛇。', '縱橫禮樂三千字，獨對丹墀日未斜。']}]}, {'chapter': '詠華清宮', 'author': '（唐）王建', 'paragraphs': ['行盡江南數十程，曉風殘月入華清。', '朝元閣上西風急，都入長楊作雨聲。']}, {'chapter': '清平調詞', 'author': '（唐）李白', 'paragraphs': ['雲想衣裳花想容，春風拂檻露華濃。', '若非羣玉山頭見，會向瑤臺月下逢。']}, {'chapter': '題邸間壁', 'author': '（宋）鄭會', 'paragraphs': ['酴醿香夢怯春寒，翠掩重門燕子閒。', '敲斷玉釵紅燭冷，計程應說到常山。']}, {'chapter': '絕句', 'author': '（唐）杜甫', 'paragraphs': ['兩個黃鸝鳴翠柳，一行白鷺上青天。', '窗含西嶺千秋雪，門泊東吳萬里船。']}, {'chapter': '海棠', 'author': '（宋）蘇軾', 'paragraphs': ['東風嫋嫋泛崇光，香霧空濛月轉廊。', '只恐夜深花睡去，故燒高燭照紅妝。']}, {'chapter': '清明', 'author': '（宋）王禹偁', 'paragraphs': ['無花無酒過清明，興味蕭然似野僧。', '昨日鄰家乞新火，曉窗分與讀書燈。']}, {'chapter': '清明', 'author': '（唐）杜牧', 'paragraphs': ['清明時節雨紛紛，路上行人慾斷魂。', '借問酒家何處有，牧童遙指杏花村。']}, {'chapter': '社日', 'author': '（唐）張演', 'paragraphs': ['鵝湖山下稻粱肥，豚柵雞棲對掩扉。', '桑柘影斜春社散，家家扶得醉人歸。']}, {'chapter': '寒食', 'author': '（唐）韓翃', 'paragraphs': ['春城無處不飛花，寒食東風御柳斜。', '日暮漢宮傳蠟燭，輕煙散入五侯家。']}, {'chapter': '江南春', 'author': '（唐）杜牧', 'paragraphs': ['千里鶯啼綠映紅，水村山郭酒旗風。', '南朝四百八十寺，多少樓臺煙雨中。']}, {'chapter': '上高侍郎', 'author': '（唐）高蟾', 'paragraphs': ['天上碧桃和露種，日邊紅杏倚雲栽。', '芙蓉生在秋江上，不向東風怨未開。']}, {'chapter': '絕句', 'author': '（宋）僧志安', 'paragraphs': ['古木陰中系短篷，杖藜扶我過橋東。', '沾衣欲溼杏花雨，吹面不寒楊柳風。']}, {'chapter': '遊小園不值', 'author': '（宋）葉紹翁', 'paragraphs': ['應嫌屐齒印蒼苔，十扣柴扉九不開。', '春色滿園關不住，一枝紅杏出牆來。']}, {'chapter': '客中行', 'author': '（唐）李白', 'paragraphs': ['蘭陵美酒鬱金香，玉碗盛來琥珀光。', '但使主人能醉客，不知何處是他鄉。']}, {'chapter': '題屏', 'author': '（宋）劉季孫', 'paragraphs': ['呢喃燕子語樑間，底事來驚夢裏閒。', '說與旁人渾不解，杖藜攜酒看芝山。']}, {'chapter': '絕句漫興', 'author': '（唐）杜甫', 'paragraphs': ['腸斷春江欲盡頭，杖藜徐步立芳洲。', '顛狂柳絮隨風舞，輕薄桃花逐水流。']}, {'chapter': '慶全庵桃花', 'author': '（宋）謝枋得', 'paragraphs': ['尋得桃源好避秦，桃紅又是一年春。', '花飛莫遣隨流水，怕有漁郎來問津。']}, {'chapter': '玄都觀桃花', 'author': '（唐）劉禹錫', 'paragraphs': ['紫陌紅塵拂面來，無人不道看花回。', '玄都觀裏桃千樹，盡是劉郎去後栽。']}, {'chapter': '再遊玄都觀', 'author': '（唐）劉禹錫', 'paragraphs': ['百畝庭中半是苔，桃花淨盡菜花開。', '種桃道士歸何處，前度劉郎今又來。']}, {'chapter': '滁州西澗', 'author': '（唐）韋應物', 'paragraphs': ['獨憐幽草澗邊生，上有黃鸝深樹鳴。', '春潮帶雨晚來急，野渡無人舟自橫。']}, {'chapter': '花影', 'author': '（宋）蘇軾', 'paragraphs': ['重重疊疊上瑤臺，幾度呼童掃不開。', '剛被太陽收拾去，卻教明月送將來。']}, {'chapter': '北山', 'author': '（宋）王安石', 'paragraphs': ['北山輸綠漲橫陂，直塹回塘灩灩時。', '細數落花因坐久，緩尋芳草得歸遲。']}, {'chapter': '湖上', 'author': '（宋）徐元傑', 'paragraphs': ['花開紅樹亂鶯啼，草長平湖白鷺飛。', '風日晴和人意好，夕陽簫鼓幾船歸。']}, {'chapter': '漫興', 'author': '（唐）杜甫', 'paragraphs': ['糝徑楊花鋪白氈，點溪荷葉疊青錢。', '筍根稚子無人見，沙上鳧雛傍母眠。']}, {'chapter': '春晴', 'author': '（宋）王駕', 'paragraphs': ['雨前初見花間蕊，雨後全無葉底花。', '蜂蝶紛紛過牆去，卻疑春色在鄰家。']}, {'chapter': '春暮', 'author': '（宋）曹豳', 'paragraphs': ['門外無人問落花，綠陰冉冉遍天涯。', '林鶯啼到無聲處，青草池塘獨聽蛙。']}, {'chapter': '落花', 'author': '（宋）朱淑貞', 'paragraphs': ['連理枝頭花正開，妒花風雨便相催。', '願教青帝常爲主，莫遣紛紛點翠苔。']}, {'chapter': '春暮遊小園', 'author': '（宋）王淇', 'paragraphs': ['一從梅粉褪殘妝，塗抹新紅上海棠。', '開到荼蘼花事了，絲絲天棘出莓牆。']}, {'chapter': '鶯梭', 'author': '（宋）劉克莊', 'paragraphs': ['擲柳遷喬太有情，交交時作弄機聲。', '洛陽三月花如錦，多少工夫織得成。']}, {'chapter': '暮春即事', 'author': '（宋）葉採', 'paragraphs': ['雙雙瓦雀行書案，點點楊花入硯池。', '閒坐小窗讀周易，不知春去幾多時。']}, {'chapter': '登山', 'author': '（唐）李涉', 'paragraphs': ['終日昏昏醉夢間，忽聞春盡強登山。', '因過竹院逢僧話，又得浮生半日閒。']}, {'chapter': '蠶婦吟', 'author': '（唐）謝枋得', 'paragraphs': ['子規啼徹四更時，起視蠶稠怕葉稀。', '不信樓頭楊柳月，玉人歌舞未曾歸。']}, {'chapter': '晚春', 'author': '（唐）韓愈', 'paragraphs': ['草樹知春不久歸，百般紅紫鬥芳菲。', '楊花榆莢無才思，惟解漫天作雪飛。']}, {'chapter': '傷春', 'author': '（宋）楊萬里', 'paragraphs': ['準擬今春樂事濃，依然枉卻一東風。', '年年不帶看花眼，不是愁中即病中。']}, {'chapter': '送春', 'author': '（宋）王令', 'paragraphs': ['三月殘花落更開，小檐日日燕飛來。', '子規夜半猶啼血，不信東風喚不回。']}, {'chapter': '三月晦日送春', 'author': '（唐）賈島', 'paragraphs': ['三月正當三十日，風光別我苦吟身。', '共君今夜不須睡，未到曉鍾猶是春。']}, {'chapter': '客中初夏', 'author': '（宋）司馬光', 'paragraphs': ['四月清和雨乍晴，南山當戶轉分明。', '更無柳絮因風起，惟有葵花向日傾。']}, {'chapter': '有約', 'author': '（宋）司馬光', 'paragraphs': ['黃梅時節家家雨，青草池塘處處蛙。', '有約不來過夜半，閒敲棋子落燈花。']}, {'chapter': '初夏睡起', 'author': '（宋）楊萬里', 'paragraphs': ['梅子流酸濺齒牙，芭蕉分綠上窗紗。', '日長睡起無情思，閒看兒童捉柳花。']}, {'chapter': '三衢道中', 'author': '（宋）曾幾', 'paragraphs': ['梅子黃時日日晴，小溪泛盡卻山行。', '綠陰不減來時路，添得黃鸝四五聲。']}, {'chapter': '即景', 'author': '（宋）朱淑貞', 'paragraphs': ['竹搖清影罩幽窗，兩兩時禽噪夕陽。', '謝卻海棠飛盡絮，困人天氣日初長。']}, {'chapter': '夏日', 'author': '（宋）戴敏', 'paragraphs': ['乳鴨池塘水淺深，熟梅天氣半晴陰。', '東園載酒西園醉，摘盡枇杷一樹金。']}, {'chapter': '晚樓閒坐', 'author': '（宋）王安石', 'paragraphs': ['四顧山光接水光，憑欄十里芰荷香。', '清風明月無人管，並作南來一味涼。']}, {'chapter': '山居夏日', 'author': '（唐）高駢', 'paragraphs': ['綠樹陰濃夏日長，樓臺倒影入池塘。', '水晶簾動微風起，滿架薔薇一院香。']}, {'chapter': '田家', 'author': '（宋）范成大', 'paragraphs': ['晝出耘田夜績麻，村莊兒女各當家。', '童孫未解供耕織，也傍桑陰學種瓜。']}, {'chapter': '村居即事', 'author': '（宋）范成大', 'paragraphs': ['綠遍山原白滿川，子規聲裏雨如煙。', '鄉村四月閒人少，才了蠶桑又插田。']}, {'chapter': '題榴花', 'author': '（宋）朱熹', 'paragraphs': ['五月榴花照眼明，枝間時見子初成。', '可憐此地無車馬，顛倒蒼苔落絳英。']}, {'chapter': '村晚', 'author': '（宋）雷震', 'paragraphs': ['草滿池塘水滿陂，山銜落日浸寒漪。', '牧童歸去橫牛背，短笛無腔信口吹。']}, {'chapter': '茅檐', 'author': '（宋）王安石', 'paragraphs': ['茅檐常掃淨無苔，花木成蹊手自栽。', '一水護田將綠繞，兩山排闥送青來。']}, {'chapter': '烏衣巷', 'author': '（唐）劉禹錫', 'paragraphs': ['朱雀橋邊野草花，烏衣巷口夕陽斜。', '舊時王謝堂前燕，飛入尋常百姓家。']}, {'chapter': '送元二使安西', 'author': '（唐）王維', 'paragraphs': ['渭城朝雨浥輕塵，客舍青青柳色新。', '勸君更盡一杯酒，西出陽關無故人。']}, {'chapter': '與史朗中飲聽黃鶴樓上吹笛', 'author': '（唐）李白', 'paragraphs': ['一爲遷客去長沙，西望長安不見家。', '黃鶴樓中吹玉笛，江城五月落梅花。']}, {'chapter': '題淮南寺', 'author': '（宋）程顥', 'paragraphs': ['南去北來休便休，白蘋吹盡楚江秋。', '道人不是悲秋客，一任晚山相對愁。']}, {'chapter': '秋月', 'author': '（宋）程顥', 'paragraphs': ['清溪流過碧山頭，空水澄鮮一色秋。', '隔斷紅塵三十里，白雲紅葉兩悠悠。']}, {'chapter': '七夕', 'author': '（宋）楊樸', 'paragraphs': ['未會牽牛意若何，須邀織女弄金梭。', '年年乞與人間巧，不道人間巧已多。']}, {'chapter': '立秋', 'author': '（宋）劉翰', 'paragraphs': ['乳鴉啼散玉屏空，一枕新涼一扇風。', '睡起秋聲無覓處，滿階梧葉月明中。']}, {'chapter': '秋夕', 'author': '（唐）杜牧', 'paragraphs': ['銀燭秋光冷畫屏，輕羅小扇撲流螢。', '天街夜色涼如水，臥看牽牛織女星。']}, {'chapter': '中秋月', 'author': '（唐）杜牧', 'paragraphs': ['暮雲收盡溢清寒，銀漢無聲轉玉盤。', '此生此夜不長好，明月明年何處看？']}, {'chapter': '江樓有感', 'author': '（唐）趙嘏', 'paragraphs': ['獨上江樓思渺然，月光如水水如天。', '同來玩月人何在，風景依稀似去年。']}, {'chapter': '題臨安邸', 'author': '（宋）林升', 'paragraphs': ['山外青山樓外樓，西湖歌舞幾時休。', '暖風薰得遊人醉，直把杭州作汴州。']}, {'chapter': '西湖', 'author': '（宋）蘇軾', 'paragraphs': ['畢竟西湖六月中，風光不與四時同。', '接天蓮葉無窮碧，映日荷花別樣紅。']}, {'chapter': '飲湖上初晴後雨', 'author': '（宋）蘇軾', 'paragraphs': ['水光瀲灩晴方好，山色空濛雨亦奇。', '欲把西湖比西子，淡妝濃抹總相宜。']}, {'chapter': '入直召對選德殿賜茶而退', 'author': '（宋）周必大', 'paragraphs': ['綠槐夾道集昏鴉，敕使傳宣坐賜茶。', '歸到玉堂清不寐，月鉤初上紫薇花。']}, {'chapter': '夏日登車蓋亭', 'author': '（宋）蔡確', 'paragraphs': ['紙屏石枕竹方牀，手倦拋書午夢長。', '睡起莞然成獨笑，數聲漁笛在滄浪。']}, {'chapter': '真玉堂作', 'author': '（宋）洪諮夔', 'paragraphs': ['禁門深鎖寂無譁，濃墨淋漓兩相麻。', '唱徹五更天未曉，一墀月浸紫薇花。']}, {'chapter': '竹樓', 'author': '（唐）李嘉佑', 'paragraphs': ['傲吏身閒笑五侯，西江取竹起高樓。', '南風不用蒲葵扇，紗帽閒眠對水鷗。']}, {'chapter': '直中書省', 'author': '（唐）白居易', 'paragraphs': ['絲綸閣下文章靜，鐘鼓樓中刻漏長。', '獨坐黃昏誰是伴，紫薇花對紫薇郎。']}, {'chapter': '觀書有感（其一）', 'author': '（宋）朱熹', 'paragraphs': ['半畝方塘一鑑開，天光雲影共徘徊。', '問渠那得清如許，爲有源頭活水來。']}, {'chapter': '泛舟', 'author': '（宋）朱熹', 'paragraphs': ['昨夜江邊春水生，艨艟鉅艦一毛輕。', '向來枉費推移力，此日中流自在行。']}, {'chapter': '冷泉亭', 'author': '（宋）林稹', 'paragraphs': ['一泓清可沁詩脾，冷暖年來只自知。', '流出西湖載歌舞，回頭不似在山時。']}, {'chapter': '冬景', 'author': '（宋）蘇軾', 'paragraphs': ['荷盡已無擎雨蓋，菊殘猶有傲霜枝。', '一年好景君須記，最是橙黃橘綠時。']}, {'chapter': '楓橋夜泊', 'author': '（唐）張繼', 'paragraphs': ['月落烏啼霜滿天，江楓漁火對愁眠。', '姑蘇城外寒山寺，夜半鐘聲到客船。']}, {'chapter': '寒夜', 'author': '（宋）杜小山', 'paragraphs': ['寒夜客來茶當酒，竹爐湯沸火初紅。', '尋常一樣窗前月，纔有梅花便不同。']}, {'chapter': '霜月', 'author': '（唐）李商隱', 'paragraphs': ['初聞徵雁已無蟬，百尺樓臺水接天。', '青女素娥俱耐冷，月中霜裏鬥嬋娟。']}, {'chapter': '梅', 'author': '（宋）王淇', 'paragraphs': ['不受塵埃半點侵，竹籬茅舍自甘心。', '只因誤識林和靖，惹得詩人說到今。']}, {'chapter': '早春', 'author': '（宋）白玉蟾', 'paragraphs': ['南枝才放兩三花，雪裏吟香弄粉些。', '淡淡著煙濃著月，深深籠水淺籠沙。']}, {'chapter': '雪梅', 'author': '（宋）盧梅坡', 'paragraphs': [{'subchapter': '其一', 'paragraphs': ['梅雪爭春未肯降，騷人閣筆費評章。', '梅須遜雪三分白，雪卻輸梅一段香。']}, {'subchapter': '其二', 'paragraphs': ['有梅無雪不精神，有雪無詩俗了人。', '日暮詩成天又雪，與梅井作十分春。']}]}, {'chapter': '答鍾弱翁', 'author': '（宋）牧童', 'paragraphs': ['草鋪橫野六七裏，笛弄晚風三四聲。', '歸來飽飯黃昏後，不脫蓑衣臥月明。']}, {'chapter': '秦淮夜泊', 'author': '（唐）杜牧', 'paragraphs': ['煙籠寒水月籠沙，夜泊秦淮近酒家。', '商女不知亡國恨，隔江猶唱後庭花。']}, {'chapter': '歸雁', 'author': '（唐）錢起', 'paragraphs': ['瀟湘何事等閒回，水碧沙明兩岸苔。', '二十五絃彈夜月，不勝清怨卻飛來。']}, {'chapter': '題壁', 'author': '無名氏', 'paragraphs': ['一團茅草亂蓬蓬，驀地燒天驀地空。', '爭似滿爐煨榾柮，漫騰騰地暖烘烘。']}]}
{'type': '七言律詩', 'content': [{'chapter': '早朝大明宮', 'author': '（唐）賈至', 'paragraphs': ['銀燭朝天紫陌長，禁城春色曉蒼蒼。', '千條弱柳垂青瑣，百囀流鶯繞建章。', '劍佩聲隨玉墀步，衣冠身惹御爐香。', '共沐恩波鳳池上，朝朝染翰侍君王。']}, {'chapter': '和賈舍人早朝', 'author': '（唐）杜甫', 'paragraphs': ['五夜漏聲催曉箭，九重春色醉仙桃。', '旌旗日暖龍蛇動，宮殿風微燕雀高。', '朝罷香菸攜滿袖，詩成珠玉在揮毫。', '欲知世掌絲綸美，池上於今有鳳毛。']}, {'chapter': '和賈舍人早朝', 'author': '（唐）王維', 'paragraphs': ['絳幘雞人報曉籌，尚衣方進翠雲裘。', '九天閶闔開宮殿，萬國衣冠拜冕旒。', '日色才臨仙掌動，香菸欲傍袞龍浮。', '朝罷須裁五色詔，佩聲歸到鳳池頭。']}, {'chapter': '和賈舍人早朝', 'author': '（唐）岑參', 'paragraphs': ['雞鳴紫陌曙光寒，鶯囀皇州春色闌。', '金闕曉鍾開萬戶，玉階仙仗擁千官。', '花迎劍佩星初落，柳拂旌旗露未乾。', '獨有鳳凰池上客，陽春一曲和皆難。']}, {'chapter': '上元應制', 'author': '（宋）蔡襄', 'paragraphs': ['高列千峯寶炬森，端門方喜翠華臨。', '宸遊不爲三元夜，樂事還同萬衆心。', '天上清光留此夕，人間和氣閣春陰。', '要知盡慶華封祝，四十餘年惠愛深。']}, {'chapter': '上元應制', 'author': '（宋）王淇', 'paragraphs': ['雪消華月滿仙台，萬燭當樓寶扇開。', '雙鳳雲中扶輦下，六鰲海上駕山來。', '鎬京春酒沾周宴，汾水秋風陋漢才。', '一曲昇平人盡樂，君王又進紫霞杯。']}, {'chapter': '侍宴', 'author': '（唐）沈佺期', 'paragraphs': ['皇家貴主好神仙，別業初開雲漢邊。', '山出盡如鳴鳳嶺，池成不讓飲龍川。', '妝樓翠幌教春住，舞閣金鋪借日懸。', '敬從乘輿來此地，稱觴獻壽樂鈞天。']}, {'chapter': '答丁元珍', 'author': '（宋）歐陽修', 'paragraphs': ['春風疑不到天涯，二月山城未見花。', '殘雪壓枝猶有橘，凍雷驚筍欲抽芽。', '夜聞啼雁生鄉思，病入新年感物華。', '曾是洛陽花下客，野芳雖晚不須嗟。']}, {'chapter': '插花吟', 'author': '（宋）邵雍', 'paragraphs': ['頭上花枝照酒卮，酒卮中有好花枝。', '身經兩世太平日，眼見四朝全盛時。', '況復筋骸粗康健，那堪時節正芳菲。', '酒涵花影紅光溜，爭忍花前不醉歸。']}, {'chapter': '寓意', 'author': '（宋）晏殊', 'paragraphs': ['油壁香車不再逢，峽雲無跡任西東。', '梨花院落溶溶月，柳絮池塘淡淡風。', '幾日寂寥傷酒後，一番蕭瑟禁菸中。', '魚書欲寄何由達，水遠山長處處同。']}, {'chapter': '寒食書事', 'author': '（宋）趙鼎', 'paragraphs': ['寂寂柴門村落裏，也教插柳紀年華。', '禁菸不到粵人國，上冢亦攜龐老家。', '漢寢唐陵無麥飯，山溪野徑有梨花。', '一樽竟藉青苔臥，莫管城頭奏暮笳。']}, {'chapter': '清明', 'author': '（宋）黃庭堅', 'paragraphs': ['佳節清明桃李笑，野田荒冢只生愁。', '雷驚天地龍蛇蟄，雨足郊原草木柔。', '人乞祭餘驕妾婦，士甘焚死不公侯。', '賢愚千載知誰是，滿眼蓬蒿共一丘。']}, {'chapter': '清明', 'author': '（宋）高菊卿', 'paragraphs': ['南北山頭多墓田，清明祭掃各紛然。', '紙灰飛作白蝴蝶，淚血染成紅杜鵑。', '日落狐狸眠冢上，夜歸兒女笑燈前。', '人生有酒須當醉，一滴何曾到九泉。']}, {'chapter': '郊行即事', 'author': '（宋）程顥', 'paragraphs': ['芳原綠野恣行時，春入遙山碧四圍。', '興逐亂紅穿柳巷，困臨流水坐苔磯。', '莫辭盞酒十分勸，只恐風花一片飛。', '況是清明好天氣，不妨遊衍莫忘歸。']}, {'chapter': '鞦韆', 'author': '（宋）僧惠洪', 'paragraphs': ['畫架雙裁翠絡偏，佳人春戲小樓前。', '飄揚血色裙拖地，斷送玉容人上天。', '花板潤沾紅杏雨，彩繩斜掛綠楊煙。', '下來閒處從容立，疑是蟾宮謫神仙。']}, {'chapter': '曲江對酒', 'author': '（唐）杜甫', 'paragraphs': [{'subchapter': '其一', 'paragraphs': ['一片花飛減卻春，風飄萬點正愁人。', '且看欲盡花經眼，莫厭傷多酒入脣。', '江上小堂巢翡翠，苑邊高冢臥麒麟。', '細推物理須行樂，何用浮名絆此身。']}, {'subchapter': '其二', 'paragraphs': ['朝回日日典春衣，每日江頭盡醉歸。', '酒債尋常行處有，人生七十古來稀。', '穿花蛺蝶深深見，點水蜻蜓款款飛。', '傳與風光共流轉，暫時相賞莫相違。']}]}, {'chapter': '黃鶴樓', 'author': '（唐）崔顥', 'paragraphs': ['昔人已乘黃鶴去，此地空餘黃鶴樓。', '黃鶴一去不復返，白雲千載空悠悠。', '晴川歷歷漢陽樹，芳草萋萋鸚鵡州。', '日暮鄉關何處是，煙波江上使人愁。']}, {'chapter': '旅懷', 'author': '（唐）崔塗', 'paragraphs': ['水流花謝兩無情，送盡東風過楚城。', '蝴蝶夢中家萬里，杜鵑枝上月三更。', '故園書動經年絕，華髮春催兩鬢生。', '自是不歸歸便得，五湖煙景有誰爭。']}, {'chapter': '答李儋', 'author': '（唐）韋應物', 'paragraphs': ['去年花裏逢君別，今日花開又一年。', '世事茫茫難自料，春愁黯黯獨成眠。', '身多疾病思田裏，邑有流亡愧俸錢。', '聞道欲來相問訊，西樓望月幾回圓。']}, {'chapter': '江村', 'author': '（唐）杜甫', 'paragraphs': ['清江一曲抱村流，長夏江村事事幽。', '自去自來樑上燕，相親相近水中鷗。', '老妻畫紙爲棋局，稚子敲針作釣鉤。', '多病所須惟藥物，微軀此外更何求。']}, {'chapter': '夏日', 'author': '（宋）張文潛', 'paragraphs': ['長夏江村風日清，檐牙燕雀已生成。', '蝶衣曬粉花枝午，蛛網添絲屋角晴。', '落落疏簾邀月影，嘈嘈虛枕納溪聲。', '久斑兩鬢如霜雪，直欲樵漁過此生。']}, {'chapter': '積雨輞川莊作', 'author': '（唐）王維', 'paragraphs': ['積雨空林煙火遲，蒸藜炊黍餉東菑。', '漠漠水田飛白鷺，陰陰夏木囀黃鸝。', '山中習靜觀朝槿，松下清齋折露葵。', '野老與人爭席罷，海鷗何事更相疑。']}, {'chapter': '新竹', 'author': '（宋）陸游', 'paragraphs': ['插棘編籬謹護持，養成寒碧映漣漪。', '清風掠地秋先到，赤日行天午不知。', '解籜時聞聲簌簌，放梢初見影離離。', '官閒我欲頻來此，枕簟仍教到處隨。']}, {'chapter': '偶成', 'author': '（宋）程顥', 'paragraphs': ['閒來無事不從容，睡覺東窗日已紅。', '萬物靜觀皆自得，四時佳興與人同。', '道通天地有形外，思入風雲變態中。', '富貴不淫貧賤樂，男兒到此是豪雄。']}, {'chapter': '表兄話舊', 'author': '（唐）竇叔向', 'paragraphs': ['夜合花開香滿庭，夜深微雨醉初醒。', '遠書珍重何由達，舊事淒涼不可聽。', '去日兒童皆長大，昔年親友半凋零。', '明朝又是孤舟別，愁見河橋酒幔青。']}, {'chapter': '遊月陂', 'author': '（宋）程顥', 'paragraphs': ['月陂堤上四徘徊，北有中天百尺臺。', '萬物已隨秋氣改，一樽聊爲晚涼開。', '水心雲影閒相照，林下泉聲靜自來。', '世事無端何足計，但逢佳節約重陪。']}, {'chapter': '秋興八首', 'author': '（唐）杜甫', 'paragraphs': [{'subchapter': '其一', 'paragraphs': ['千家山郭靜朝暉，日日江樓坐翠微。', '信宿漁人還泛泛，清秋燕子故飛飛。', '匡衡抗疏功名薄，劉向傳經心事違。', '同學少年多不賤，五陵裘馬自輕肥。']}, {'subchapter': '其二', 'paragraphs': ['蓬萊宮闕對南山，承露金莖霄漢間。', '西望瑤池降王母，東來紫氣滿函關。', '雲移雉尾開宮扇，日繞龍鱗識聖顏。', '一臥滄江驚歲晚，幾回青瑣點朝班。']}, {'subchapter': '其三', 'paragraphs': ['玉露凋傷楓樹林，巫山巫峽氣蕭森。', '江間波浪兼天涌，塞上風雲接地陰。', '叢菊兩開他日淚，孤舟一系故園心。', '寒衣處處催刀尺，白帝城高急暮砧。']}, {'subchapter': '其四', 'paragraphs': ['昆明池水漢時功，武帝旌旗在眼中。', '織女機絲虛夜月，石鯨鱗甲動秋風。', '波飄菰米沉雲黑，露冷蓮房墜粉紅。', '關塞極天惟鳥道，江湖滿地一漁翁。']}]}, {'chapter': '月夜舟中', 'author': '（宋）戴復古', 'paragraphs': ['滿船明月浸虛空，綠水無痕夜氣衝。', '詩思浮沈檣影裏，夢魂搖拽櫓聲中。', '星辰冷落碧潭水，鴻雁悲鳴紅蓼風。', '數點漁燈依古岸，斷橋垂露滴梧桐。']}, {'chapter': '長安秋望', 'author': '（唐）趙嘏', 'paragraphs': ['雲物淒涼拂曙流，漢家宮闕動高秋。', '殘星幾點雁橫塞，長笛一聲人倚樓。', '紫豔半開籬菊靜，紅衣落盡渚蓮愁。', '鱸魚正美不歸去，空戴南冠學楚囚。']}, {'chapter': '新秋', 'author': '（唐）杜甫', 'paragraphs': ['火雲猶未斂奇峯，欹枕初驚一葉風。', '幾處園林蕭瑟裏，誰家砧杵寂寥中。', '蟬聲斷續悲殘月，螢焰高低照暮空。', '賦就金門期再獻，夜深搔首嘆飛蓬。']}, {'chapter': '中秋', 'author': '（宋）李樸', 'paragraphs': ['皓魄當空寶鏡升，雲間仙籟寂無聲。', '平分秋色一輪滿，長伴雲衢千里明。', '狡兔空從弦外落，妖蟆休向眼前生。', '靈槎擬約同攜手，更待銀河澈底清。']}, {'chapter': '九日藍耕會飲', 'author': '（唐）杜甫', 'paragraphs': ['老去悲秋強自寬，興來今日盡君歡。', '羞將短髮還吹帽，笑倩旁人爲正冠。', '藍水遠從千澗落，玉山高並兩峯寒。', '明年此會知誰健，醉把茱萸仔細看。']}, {'chapter': '秋思', 'author': '（宋）陸游', 'paragraphs': ['利慾驅人萬火牛，江湖浪跡一沙鷗。', '日長似歲閒方覺，事大如天醉亦休。', '砧杵敲殘深巷月，梧桐搖落故園秋。', '欲舒老眼無高處，安得元龍百尺樓。']}, {'chapter': '與朱山人', 'author': '（唐）杜甫', 'paragraphs': ['錦裏先生烏角巾，園收芋慄未全貧。', '慣看賓客兒童喜，得食階除鳥雀馴。', '秋水才深四五尺，野航恰受兩三人。', '白沙翠竹江村暮，相送柴門月色新。']}, {'chapter': '聞笛', 'author': '（唐）趙嘏', 'paragraphs': ['誰家吹笛畫樓中，斷續聲隨斷續風。', '響遏行雲橫碧落，清和冷月到簾櫳。', '興來三弄有桓子，賦就一篇懷馬融。', '曲罷不知人在否，餘音嘹亮尚飄空。']}, {'chapter': '冬景', 'author': '（宋）劉克莊', 'paragraphs': ['晴窗早覺愛朝曦，竹外秋聲漸作威。', '命僕安排新暖閣，呼童熨貼舊寒衣。', '葉浮嫩綠酒初熟，橙切香黃蟹正肥。', '蓉菊滿園皆可羨，賞心從此莫相違。']}, {'chapter': '冬至', 'author': '（唐）杜甫', 'paragraphs': ['天時人事日相催，冬至陽生春又來。', '刺繡五紋添弱線，吹葭六管動飛灰。', '岸容待臘將舒柳，山意衝寒欲放梅。', '雲物不殊鄉國異，教兒且覆掌中杯。']}, {'chapter': '梅花', 'author': '（宋）林逋', 'paragraphs': ['衆芳搖落獨鮮妍，占斷風情向小園。', '疏影橫斜水清淺，暗香浮動月黃昏。', '霜禽欲下先偷眼，粉蝶如知合斷魂。', '幸有微吟可相狎，不須檀板共金樽。']}, {'chapter': '左遷至藍關示侄孫湘', 'author': '（唐）韓愈', 'paragraphs': ['一封朝奏九重天，夕貶潮陽路八千。', '本爲聖朝除弊政，敢將衰朽惜殘年。', '雲橫秦嶺家何在，雪擁藍關馬不前。', '知汝遠來應有意，好收吾骨瘴江邊。']}, {'chapter': '干戈', 'author': '（宋）王中', 'paragraphs': ['干戈未定欲何之，一事無成兩鬢絲。', '蹤跡大綱王粲傳，情懷小樣杜陵詩。', '鶺鴒音斷人千里，烏鵲巢寒月一枝。', '安得中山千日酒，酩然直到太平時。']}, {'chapter': '歸隱', 'author': '（宋）陳摶', 'paragraphs': ['十年蹤跡走紅塵，回首青山入夢頻。', '紫綬縱榮爭及睡，朱門雖富不如貧。', '愁聞劍戟扶危主，悶聽笙歌聒醉人。', '攜取舊書歸舊隱，野花啼鳥一般春。']}, {'chapter': '山中寡婦', 'author': '（唐）杜荀鶴', 'paragraphs': ['夫因兵亂守蓬茅，麻苧裙衫鬢髮焦。', '桑柘廢來猶納稅，田園荒盡尚徵苗。', '時挑野菜和根煮，旋砍生柴帶葉燒。', '任是深山最深處，也應無計避徵徭。']}, {'chapter': '送天師', 'author': '（明）朱權', 'paragraphs': ['霜落芝城柳影疏，殷勤送客出鄱湖。', '黃金甲鎖雷霆印，紅錦韜纏日月符。', '天上曉行騎只鶴，人間夜宿解雙鳧。', '匆匆歸到神仙府，爲問蟠桃熟也無。']}, {'chapter': '送毛伯溫', 'author': '（明）明世宗', 'paragraphs': ['大將南征膽氣豪，腰橫秋水雁翎刀。', '風吹鼉鼓山河動，電閃旌旗日月高。', '天上麒麟原有種，穴中螻蟻豈能逃。', '太平待詔歸來日，朕與先生解戰袍。']}]}
